insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('91d29025-e976-4d62-8050-e6e64c266de9', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Biological Anthropology as Evolutionary Human Science', 'This opening unit frames biological anthropology as the study of humans and our relatives through evolution, biology, behavior, ecology, fossils, genetics, and culture. Students learn how the field connects natural science with anthropological questions about human diversity and origins.', 0),
  ('35f58221-ed63-4507-9237-1602a36ab93f', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '91d29025-e976-4d62-8050-e6e64c266de9', 'subtopic'::public.curated_course_node_type, 'Four-field anthropology and biological anthropology', 'Students locate biological anthropology within anthropology''s broader concern with human beings across time, place, and evidence.', 0),
  ('ee11ea43-464e-4765-b2f1-32c99e806846', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '35f58221-ed63-4507-9237-1602a36ab93f', 'concept'::public.curated_course_node_type, 'Cultural, archaeological, linguistic, and biological anthropology', null, 0),
  ('92c2688c-1bcf-4ef2-9b17-92c7f220299f', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '35f58221-ed63-4507-9237-1602a36ab93f', 'concept'::public.curated_course_node_type, 'Human biology in cultural context', null, 1),
  ('17b3eae2-b975-45a1-b6ad-804a877c2dd8', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '35f58221-ed63-4507-9237-1602a36ab93f', 'concept'::public.curated_course_node_type, 'Holism and comparison', null, 2),
  ('ddde8a75-a261-4633-a8ad-5090033f9088', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '91d29025-e976-4d62-8050-e6e64c266de9', 'subtopic'::public.curated_course_node_type, 'Evidence and scales of analysis', 'This subtopic introduces the types of evidence used to study human evolution and variation.', 1),
  ('e2d0b62e-0575-4c22-95eb-24f2e19dcad0', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ddde8a75-a261-4633-a8ad-5090033f9088', 'concept'::public.curated_course_node_type, 'Fossils and artifacts', null, 0),
  ('b16d3b3e-f636-497e-87f5-83eaed576c58', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ddde8a75-a261-4633-a8ad-5090033f9088', 'concept'::public.curated_course_node_type, 'Genes and populations', null, 1),
  ('3bb4198f-cde7-4ac3-9b13-ed6a6d7eb83d', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ddde8a75-a261-4633-a8ad-5090033f9088', 'concept'::public.curated_course_node_type, 'Behavior, ecology, and life history', null, 2),
  ('61d75b7d-6f4a-4c49-946f-52635b7b83cf', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '91d29025-e976-4d62-8050-e6e64c266de9', 'subtopic'::public.curated_course_node_type, 'Scientific reasoning in human origins', 'Students learn how hypotheses about the past are built, tested, revised, and debated.', 2),
  ('784e09e6-8856-4511-945c-8aa0f46beb0c', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '61d75b7d-6f4a-4c49-946f-52635b7b83cf', 'concept'::public.curated_course_node_type, 'Inference from incomplete evidence', null, 0),
  ('24e569ae-5fd1-41a1-8395-162599a4fb3e', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '61d75b7d-6f4a-4c49-946f-52635b7b83cf', 'concept'::public.curated_course_node_type, 'Multiple working hypotheses', null, 1),
  ('a58907df-4a3c-4f4d-9b31-2de1764f3259', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '61d75b7d-6f4a-4c49-946f-52635b7b83cf', 'concept'::public.curated_course_node_type, 'Uncertainty and peer review', null, 2),
  ('71be3305-01a6-42d6-89d6-b28b7867a8fe', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Evolutionary Theory and Natural Selection', 'Evolution is the foundation of biological anthropology. This unit gives students the core mechanisms needed to explain biological change without teleology or ladder-like thinking.', 1),
  ('8b2fe8e9-73a6-43ef-9de4-857cc57ec2d5', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '71be3305-01a6-42d6-89d6-b28b7867a8fe', 'subtopic'::public.curated_course_node_type, 'Darwin, descent with modification, and selection', 'Students learn how variation, inheritance, differential survival, and reproduction generate adaptation over time.', 0),
  ('a378bc7a-502f-4bf9-ac59-dacb1e1c26c5', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '8b2fe8e9-73a6-43ef-9de4-857cc57ec2d5', 'concept'::public.curated_course_node_type, 'Variation and heritability', null, 0),
  ('3bb86cba-d372-461f-80fa-adafed6d02dc', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '8b2fe8e9-73a6-43ef-9de4-857cc57ec2d5', 'concept'::public.curated_course_node_type, 'Fitness and reproductive success', null, 1),
  ('21d6365a-ecf3-4214-94d3-b03866b58d04', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '8b2fe8e9-73a6-43ef-9de4-857cc57ec2d5', 'concept'::public.curated_course_node_type, 'Adaptation and constraint', null, 2),
  ('b7122dc2-9cc9-4e61-b97b-07d82a3663e2', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '71be3305-01a6-42d6-89d6-b28b7867a8fe', 'subtopic'::public.curated_course_node_type, 'Mechanisms of evolution', 'This subtopic expands beyond natural selection to show how populations change.', 1),
  ('ead7ae87-e6dc-4e58-8e8d-6c7d37950513', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'b7122dc2-9cc9-4e61-b97b-07d82a3663e2', 'concept'::public.curated_course_node_type, 'Mutation and recombination', null, 0),
  ('aea8d101-40d4-4182-8641-7170425672de', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'b7122dc2-9cc9-4e61-b97b-07d82a3663e2', 'concept'::public.curated_course_node_type, 'Genetic drift and gene flow', null, 1),
  ('7801a675-4e44-4e42-a6f6-57d36f0231b3', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'b7122dc2-9cc9-4e61-b97b-07d82a3663e2', 'concept'::public.curated_course_node_type, 'Sexual selection', null, 2),
  ('6c9b7fe0-19b9-44cc-a527-18192f082d35', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '71be3305-01a6-42d6-89d6-b28b7867a8fe', 'subtopic'::public.curated_course_node_type, 'Phylogeny and tree thinking', 'Students learn to reason about relatedness using branching models rather than linear progress narratives.', 2),
  ('ec3c6862-9045-46a6-949e-14e81a31af19', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6c9b7fe0-19b9-44cc-a527-18192f082d35', 'concept'::public.curated_course_node_type, 'Common ancestry', null, 0),
  ('096e4c41-c922-43f5-b66c-5328bb9c86d5', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6c9b7fe0-19b9-44cc-a527-18192f082d35', 'concept'::public.curated_course_node_type, 'Clades and outgroups', null, 1),
  ('efa688d2-bfc2-46aa-9ed7-49d39457f406', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6c9b7fe0-19b9-44cc-a527-18192f082d35', 'concept'::public.curated_course_node_type, 'Homology and analogy', null, 2),
  ('82b9787a-138d-489d-a0a6-8fcd42cf9dd9', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Genetics, Inheritance, and Population Variation', 'Biological anthropology requires genetics at the level of individuals, families, and populations. This unit links molecular inheritance with evolutionary processes and human diversity.', 2),
  ('402014e5-add2-431c-941e-27cce66eb190', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '82b9787a-138d-489d-a0a6-8fcd42cf9dd9', 'subtopic'::public.curated_course_node_type, 'Mendelian and molecular foundations', 'Students review the inheritance concepts needed to understand traits and variation.', 0),
  ('71bfb191-6bfa-40f2-97eb-57213a644f5c', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '402014e5-add2-431c-941e-27cce66eb190', 'concept'::public.curated_course_node_type, 'DNA, genes, and alleles', null, 0),
  ('931b5ada-9b63-444b-9eb0-cf5048936317', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '402014e5-add2-431c-941e-27cce66eb190', 'concept'::public.curated_course_node_type, 'Mendelian inheritance', null, 1),
  ('7ab943a9-8dee-4138-941e-fc8377f0f28d', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '402014e5-add2-431c-941e-27cce66eb190', 'concept'::public.curated_course_node_type, 'Genotype and phenotype', null, 2),
  ('4b9eec4d-726f-4e95-b918-06ffd5bc2233', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '82b9787a-138d-489d-a0a6-8fcd42cf9dd9', 'subtopic'::public.curated_course_node_type, 'Population genetics', 'This subtopic introduces allele frequencies, Hardy-Weinberg expectations, and forces that shift genetic variation.', 1),
  ('0b785896-b3a5-4eb8-bb69-173844e5cbd2', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '4b9eec4d-726f-4e95-b918-06ffd5bc2233', 'concept'::public.curated_course_node_type, 'Allele frequencies', null, 0),
  ('dec9b92d-346d-4ba2-a2ce-0af9db49c372', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '4b9eec4d-726f-4e95-b918-06ffd5bc2233', 'concept'::public.curated_course_node_type, 'Hardy-Weinberg equilibrium', null, 1),
  ('4785cda6-b315-4a87-98a2-20d60ac302b1', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '4b9eec4d-726f-4e95-b918-06ffd5bc2233', 'concept'::public.curated_course_node_type, 'Population structure', null, 2),
  ('75e35c07-171d-4763-b277-0f69f4ed3515', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '82b9787a-138d-489d-a0a6-8fcd42cf9dd9', 'subtopic'::public.curated_course_node_type, 'Human genetic diversity', 'Students learn how variation is patterned by ancestry, migration, adaptation, drift, and gene flow.', 2),
  ('1cd2068c-fa99-48bb-a7fb-dbd2975a9dae', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '75e35c07-171d-4763-b277-0f69f4ed3515', 'concept'::public.curated_course_node_type, 'Clines and gradients', null, 0),
  ('675faa8d-b7f0-4028-ac90-cbc664a4c869', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '75e35c07-171d-4763-b277-0f69f4ed3515', 'concept'::public.curated_course_node_type, 'Founder effects', null, 1),
  ('c655cb26-3e09-4f78-924c-000ab74aaf20', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '75e35c07-171d-4763-b277-0f69f4ed3515', 'concept'::public.curated_course_node_type, 'Admixture and ancestry inference', null, 2),
  ('54f600dc-86c1-4646-9857-8987b67b949b', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Primate Taxonomy, Ecology, and Behavior', 'Primates provide comparative context for understanding human evolution. This unit introduces primate diversity, social behavior, ecology, cognition, and conservation.', 3);
