  ('ce0be309-7cab-4d11-bf8f-e74f3b49f627', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'fda7d03b-54bd-4717-a589-87c69563418f', 'concept'::public.curated_course_node_type, 'Tool use and communication', null, 1),
  ('a997ba4d-4ff2-42a4-bdd4-04d2562052fd', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'fda7d03b-54bd-4717-a589-87c69563418f', 'concept'::public.curated_course_node_type, 'Habitat loss and conservation ethics', null, 2),
  ('c31e0ada-010d-4519-a4e9-54c4bed504d2', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Human Skeletal Anatomy and Osteology', 'Skeletal anatomy is a core evidence base for biological anthropology. Students learn how bones record locomotion, growth, sex, age, health, ancestry, trauma, and evolutionary history.', 4),
