  ('fce58824-df38-459f-9c9d-46fb228fa796', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ed26c963-e6e9-4654-ae42-d9e403a2ce9b', 'concept'::public.curated_course_node_type, 'Axial and appendicular skeleton', null, 0),
