  ('5c86ce93-b3b6-456f-ba58-02981db5dab4', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'e72f73ad-499c-4baa-a940-1f9b3d7e9d11', 'concept'::public.curated_course_node_type, 'Dentition and chewing', null, 1),
