  ('1d9d7aaf-d3f9-4d44-99e1-bc1b92384746', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '244b6952-7797-49b1-a3f8-c6a62b632ff6', 'concept'::public.curated_course_node_type, 'Age and sex estimation', null, 0),
  ('326f8c3b-d09a-4041-8961-94d3d893503b', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '244b6952-7797-49b1-a3f8-c6a62b632ff6', 'concept'::public.curated_course_node_type, 'Metric and nonmetric traits', null, 1),
  ('1539d2a1-2af0-4f8f-871d-96858eb3d24e', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '244b6952-7797-49b1-a3f8-c6a62b632ff6', 'concept'::public.curated_course_node_type, 'Uncertainty and population reference samples', null, 2),
  ('2e5346c2-6f44-4229-9560-3409861b70d9', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Fossilization, Dating, and Paleoanthropological Evidence', 'Human evolution is reconstructed from fragmentary traces preserved in geological context. This unit teaches students how paleoanthropologists build evidence from fossils, sites, sediments, dates, and comparative anatomy.', 5),
  ('e2fd6576-fdbc-48a0-9951-8cb42377fb8b', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '2e5346c2-6f44-4229-9560-3409861b70d9', 'subtopic'::public.curated_course_node_type, 'Fossilization and site formation', 'Students learn why fossil evidence is rare, biased, and context-dependent.', 0),
  ('ceccecd7-ff4b-4f3b-bc35-894b6dc51368', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'e2fd6576-fdbc-48a0-9951-8cb42377fb8b', 'concept'::public.curated_course_node_type, 'Taphonomy', null, 0),
  ('3e9e298b-338f-4872-9c86-57c455678bb0', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'e2fd6576-fdbc-48a0-9951-8cb42377fb8b', 'concept'::public.curated_course_node_type, 'Preservation bias', null, 1),
  ('ee3eccf9-5fda-4222-bce1-ab9bf650fc80', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'e2fd6576-fdbc-48a0-9951-8cb42377fb8b', 'concept'::public.curated_course_node_type, 'Depositional context', null, 2),
  ('dd73d8e6-07fc-4f17-bebc-c80901deba2e', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '2e5346c2-6f44-4229-9560-3409861b70d9', 'subtopic'::public.curated_course_node_type, 'Dating methods and chronology', 'This subtopic introduces relative and absolute dating methods used to place fossils and artifacts in time.', 1),
  ('8caf61e7-6736-44d0-914e-cf6e454a730d', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'dd73d8e6-07fc-4f17-bebc-c80901deba2e', 'concept'::public.curated_course_node_type, 'Stratigraphy', null, 0),
  ('8e87b816-9341-4a3b-af20-7e5cc9a4b2d9', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'dd73d8e6-07fc-4f17-bebc-c80901deba2e', 'concept'::public.curated_course_node_type, 'Radiometric dating', null, 1),
  ('fdc70a09-ae68-4976-8487-4739e2883ac7', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'dd73d8e6-07fc-4f17-bebc-c80901deba2e', 'concept'::public.curated_course_node_type, 'Paleomagnetism and biostratigraphy', null, 2),
  ('ed7c185f-0f6f-4d02-b048-4a288876f9a2', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '2e5346c2-6f44-4229-9560-3409861b70d9', 'subtopic'::public.curated_course_node_type, 'Comparative fossil analysis', 'Students practice reading fossil traits as evidence for evolutionary relationships and behavior.', 2),
  ('82349d95-816a-4a4e-9459-e0876ed6d271', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ed7c185f-0f6f-4d02-b048-4a288876f9a2', 'concept'::public.curated_course_node_type, 'Cranial and dental traits', null, 0),
  ('f3fb9495-0380-4d02-a511-62187520cb6a', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ed7c185f-0f6f-4d02-b048-4a288876f9a2', 'concept'::public.curated_course_node_type, 'Postcranial anatomy', null, 1),
  ('230598b4-7e0f-45e1-97fb-05f09d2f825a', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'ed7c185f-0f6f-4d02-b048-4a288876f9a2', 'concept'::public.curated_course_node_type, 'Mosaic evolution', null, 2),
  ('eea09093-2da7-4334-9e29-93884b424309', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Early Hominins and the Evolution of Bipedalism', 'Bipedalism is one of the defining shifts in hominin evolution. This unit examines early hominins, environmental context, locomotor anatomy, and debates about why upright walking evolved.', 6),
  ('57880317-ce76-47c4-8404-66d04ee37479', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'eea09093-2da7-4334-9e29-93884b424309', 'subtopic'::public.curated_course_node_type, 'Defining hominins', 'Students learn how scientists identify early members of the human lineage.', 0);
