  ('a7842f17-781a-4c0d-958d-cc1f11b55b77', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '9a469f87-b8f3-436b-9b64-ef04cca939da', 'concept'::public.curated_course_node_type, 'Costs and benefits of bipedality', null, 2),
  ('dff789f2-1b13-451f-a580-c8dd8e221d3e', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Genus Homo, Technology, and Pleistocene Dispersals', 'This unit follows the emergence of Homo and the expansion of hominins across Africa and Eurasia. Students connect anatomy, brains, tools, diet, cooperation, and changing environments.', 7),
  ('e7cb8735-fd70-4405-91e4-911594f16e47', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'dff789f2-1b13-451f-a580-c8dd8e221d3e', 'subtopic'::public.curated_course_node_type, 'Early Homo and adaptive shifts', 'Students examine anatomical and behavioral changes associated with early Homo.', 0),
  ('639fa854-2365-4e0f-88f3-bf14e45fd6f6', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'e7cb8735-fd70-4405-91e4-911594f16e47', 'concept'::public.curated_course_node_type, 'Brain and body size', null, 0),
