  ('c6d41018-8c2d-45c6-8f59-f5d3ce4109dd', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'e7cb8735-fd70-4405-91e4-911594f16e47', 'concept'::public.curated_course_node_type, 'Oldowan technology', null, 2),
  ('157aa12a-97f2-482c-a8dd-7b20173b71c3', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'dff789f2-1b13-451f-a580-c8dd8e221d3e', 'subtopic'::public.curated_course_node_type, 'Homo erectus and dispersal', 'This subtopic studies long-distance movement, Acheulean tools, endurance, and ecological flexibility.', 1),
