  ('25348c85-a9f7-4aa1-b7b8-bd2ba3066933', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'dff789f2-1b13-451f-a580-c8dd8e221d3e', 'subtopic'::public.curated_course_node_type, 'Pleistocene variability', 'Students learn that Homo evolution was branching, regional, and diverse rather than linear.', 2),
  ('cf4fafdd-3354-41c7-9e9b-4439e8729c00', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '25348c85-a9f7-4aa1-b7b8-bd2ba3066933', 'concept'::public.curated_course_node_type, 'Regional populations', null, 0),
  ('ff53cb74-4046-4fb5-9208-9e761332afef', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '25348c85-a9f7-4aa1-b7b8-bd2ba3066933', 'concept'::public.curated_course_node_type, 'Climate cycles', null, 1),
  ('17cb0d24-e7ea-4fbe-9e7d-434fc62c20ce', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '25348c85-a9f7-4aa1-b7b8-bd2ba3066933', 'concept'::public.curated_course_node_type, 'Species debates', null, 2),
  ('afac4d4b-2ab1-476d-a179-0f92cc654827', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Neanderthals, Denisovans, Ancient DNA, and Admixture', 'Ancient DNA has transformed human origins research. This unit examines late archaic humans, interbreeding, adaptation, extinction, and how genetic evidence changes fossil interpretation.', 8),
