  ('f6f750fb-c59e-418c-98e7-829030380880', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '646ccba8-aeb6-4205-8684-84640da67345', 'concept'::public.curated_course_node_type, 'Cold adaptation', null, 0),
