  ('28730ce2-c81a-4d6c-a9c2-71dd89812e73', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'afac4d4b-2ab1-476d-a179-0f92cc654827', 'subtopic'::public.curated_course_node_type, 'Denisovans and other archaic populations', 'This subtopic introduces genetic lineages known from limited fossil evidence.', 1),
