  ('4beab602-e552-458f-9f68-32a6272e93f9', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'f5f920bd-43ba-4564-b45b-200e9b377eb3', 'concept'::public.curated_course_node_type, 'Adaptive variants', null, 1),
  ('72beb0d0-aab4-44af-8869-1803bc2f0d10', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'f5f920bd-43ba-4564-b45b-200e9b377eb3', 'concept'::public.curated_course_node_type, 'Contamination and consent', null, 2),
