  ('6b8bcbe1-69ee-4afe-b80c-97155239d779', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Human Biological Variation and the Critique of Race', 'Biological anthropology has a responsibility to explain human variation accurately and challenge racial typologies. This unit teaches students why race is not a valid biological taxonomy while racism has real biological consequences.', 10),
  ('6bf79ee0-c7c4-4cf4-8683-a870a7abcd39', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6b8bcbe1-69ee-4afe-b80c-97155239d779', 'subtopic'::public.curated_course_node_type, 'Patterns of human variation', 'Students learn that human traits vary clinally, historically, and adaptively rather than as bounded races.', 0),
  ('47e4e2d4-896a-4174-86df-76d88bfdc3d3', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6bf79ee0-c7c4-4cf4-8683-a870a7abcd39', 'concept'::public.curated_course_node_type, 'Clines', null, 0),
  ('1b6ef3ee-371f-495a-b363-45d22e334b37', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6bf79ee0-c7c4-4cf4-8683-a870a7abcd39', 'concept'::public.curated_course_node_type, 'Within-group variation', null, 1),
  ('1ef2fc51-a2f4-4c7b-8123-62bc358cfb68', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6bf79ee0-c7c4-4cf4-8683-a870a7abcd39', 'concept'::public.curated_course_node_type, 'Gene flow and migration', null, 2),
  ('827e8e84-aa14-4882-b43f-ddfbc5ec763a', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6b8bcbe1-69ee-4afe-b80c-97155239d779', 'subtopic'::public.curated_course_node_type, 'Race, racism, and biology', 'This subtopic distinguishes social race from biological ancestry and examines the health effects of racism.', 1),
  ('f607ac56-8a23-4ccd-93ec-1cf9c5dfe51f', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '827e8e84-aa14-4882-b43f-ddfbc5ec763a', 'concept'::public.curated_course_node_type, 'Race as social classification', null, 0),
  ('d652ae94-54d2-46f1-94fb-8217e574f297', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '827e8e84-aa14-4882-b43f-ddfbc5ec763a', 'concept'::public.curated_course_node_type, 'Ancestry versus race', null, 1),
  ('f1dad751-5e86-4e20-8de1-ae700f21968e', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '827e8e84-aa14-4882-b43f-ddfbc5ec763a', 'concept'::public.curated_course_node_type, 'Embodiment of inequality', null, 2),
  ('fe87a0e6-7fe4-45ac-acd0-fad047fca24a', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6b8bcbe1-69ee-4afe-b80c-97155239d779', 'subtopic'::public.curated_course_node_type, 'Communicating variation responsibly', 'Students practice avoiding genetic determinism, typological thinking, and misuse of ancestry data.', 2),
  ('40e7b888-6781-4dcd-8b5d-89f4eba34d17', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'fe87a0e6-7fe4-45ac-acd0-fad047fca24a', 'concept'::public.curated_course_node_type, 'Trait complexity', null, 0),
  ('4c2eb080-600d-4740-bd8d-f11071dbfb0f', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'fe87a0e6-7fe4-45ac-acd0-fad047fca24a', 'concept'::public.curated_course_node_type, 'Population labels', null, 1),
  ('aeb9ad6d-8eba-4c74-a31d-414f6a56475e', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', 'fe87a0e6-7fe4-45ac-acd0-fad047fca24a', 'concept'::public.curated_course_node_type, 'Ethical communication', null, 2),
