  ('8cc82432-714e-4d8f-9aa2-d66c71706c3d', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '4d50ffe3-7eb5-4c5c-92b6-8fc13a371cc0', 'subtopic'::public.curated_course_node_type, 'Climate and body form', 'Students learn how body size, limb proportions, and physiology relate to thermal environments.', 0),
  ('bedbdd3e-bd9b-4d05-852f-1a9c98e91983', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '8cc82432-714e-4d8f-9aa2-d66c71706c3d', 'concept'::public.curated_course_node_type, 'Bergmann''s and Allen''s rules', null, 0),
  ('da52d376-89ec-4813-9615-8544af782f96', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '8cc82432-714e-4d8f-9aa2-d66c71706c3d', 'concept'::public.curated_course_node_type, 'Heat and cold stress', null, 1),
  ('ac8ee9f9-6dea-43b9-881e-d211789ae7c4', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '8cc82432-714e-4d8f-9aa2-d66c71706c3d', 'concept'::public.curated_course_node_type, 'Plasticity and acclimatization', null, 2),
  ('6eb8c5e3-3053-4400-9568-92af1c9ec214', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '4d50ffe3-7eb5-4c5c-92b6-8fc13a371cc0', 'subtopic'::public.curated_course_node_type, 'Diet and gene-culture coevolution', 'This subtopic connects subsistence, agriculture, lactose digestion, starch digestion, and microbiomes.', 1),
  ('b1da52da-acac-4f69-9887-a7636f813117', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6eb8c5e3-3053-4400-9568-92af1c9ec214', 'concept'::public.curated_course_node_type, 'Lactase persistence', null, 0),
