  ('13651612-c50c-42c3-8e05-5f5eb3315895', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '6eb8c5e3-3053-4400-9568-92af1c9ec214', 'concept'::public.curated_course_node_type, 'Agriculture and selection', null, 2),
  ('3dbbcc16-bded-42e9-9146-628afd40c186', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '4d50ffe3-7eb5-4c5c-92b6-8fc13a371cc0', 'subtopic'::public.curated_course_node_type, 'Disease and altitude adaptation', 'Students study malaria, sickle-cell traits, immune variation, and high-altitude physiology.', 2),
  ('7b4ac502-2cd7-4916-8b13-08fd6dda63ee', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '3dbbcc16-bded-42e9-9146-628afd40c186', 'concept'::public.curated_course_node_type, 'Balanced polymorphism', null, 0),
  ('b8aef18f-7393-40ed-a2d5-186e2d8c50ba', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '3dbbcc16-bded-42e9-9146-628afd40c186', 'concept'::public.curated_course_node_type, 'Hypoxia adaptation', null, 1),
  ('1d7d78bd-32fb-46cb-9776-5ddaaf3bcd1c', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '3dbbcc16-bded-42e9-9146-628afd40c186', 'concept'::public.curated_course_node_type, 'Pathogens and selection', null, 2),
  ('3da9b89b-2ea1-45ad-b1b5-f2bda5fe85b8', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', null, 'topic'::public.curated_course_node_type, 'Life History, Growth, Development, and Reproduction', 'Human bodies are shaped across the life course. This unit examines growth, childhood, adolescence, reproduction, aging, and the evolutionary tradeoffs that make human life history distinctive.', 12),
