  ('7654db15-de41-465f-9db3-8fe013016781', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '983baa89-2815-4270-8f40-287af8b0cca4', 'concept'::public.curated_course_node_type, 'Growth curves', null, 0),
  ('f6e5763d-43f7-4a1c-9214-1263622974a8', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '983baa89-2815-4270-8f40-287af8b0cca4', 'concept'::public.curated_course_node_type, 'Developmental plasticity', null, 1);
