  ('3e5cfdf5-3b13-4df5-ac12-438a3a78205d', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '1305b23a-b99f-4d08-ba2a-3850b38d411a', 'concept'::public.curated_course_node_type, 'Activity patterns', null, 1),
  ('892eb3df-d567-4e4a-b9a0-3ae24b4c6f40', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '1305b23a-b99f-4d08-ba2a-3850b38d411a', 'concept'::public.curated_course_node_type, 'Population-level interpretation', null, 2),
