  ('af070d4c-b06f-4ebf-b616-2b045b09ee46', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '3c49ce06-e95c-45d1-ae9a-1f747fe69920', 'concept'::public.curated_course_node_type, 'Thrifty genotype and phenotype debates', null, 0),
  ('87520972-96d0-4d03-8b13-6012d1ea89a8', 'a1b2c3d4-5e6f-4b21-8c01-1d2e3f4a5b11', '3c49ce06-e95c-45d1-ae9a-1f747fe69920', 'concept'::public.curated_course_node_type, 'Sedentism and diet', null, 1),
