  'Biological / Physical Anthropology',
  'Biological / Physical Anthropology',
  'Biological / Physical Anthropology introduces human evolution and biological diversity through evolutionary theory, genetics, primatology, skeletal anatomy, paleoanthropology, bioarchaeology, forensics, adaptation, and ethics. The course emphasizes scientific reasoning, multiple lines of evidence, anti-racist communication about human variation, and respectful work with human remains and descendant communities.',
  $bpanjson${"slug": "biological-physical-anthropology", "title": "Biological / Physical Anthropology", "description": "Biological / Physical Anthropology introduces human evolution and biological diversity through evolutionary theory, genetics, primatology, skeletal anatomy, paleoanthropology, bioarchaeology, forensics, adaptation, and ethics. The course emphasizes scientific reasoning, multiple lines of evidence, anti-racist communication about human variation, and respectful work with human remains and descendant communities.", "topics": [{"id": "91d29025-e976-4d62-8050-e6e64c266de9", "type": "topic", "title": "Biological Anthropology as Evolutionary Human Science", "description": "This opening unit frames biological anthropology as the study of humans and our relatives through evolution, biology, behavior, ecology, fossils, genetics, and culture. Students learn how the field connects natural science with anthropological questions about human diversity and origins.", "children": [{"id": "35f58221-ed63-4507-9237-1602a36ab93f", "type": "subtopic", "title": "Four-field anthropology and biological anthropology", "children": [{"id": "ee11ea43-464e-4765-b2f1-32c99e806846", "type": "concept", "title": "Cultural, archaeological, linguistic, and biological anthropology"}, {"id": "92c2688c-1bcf-4ef2-9b17-92c7f220299f", "type": "concept", "title": "Human biology in cultural context"}, {"id": "17b3eae2-b975-45a1-b6ad-804a877c2dd8", "type": "concept", "title": "Holism and comparison"}], "description": "Students locate biological anthropology within anthropology's broader concern with human beings across time, place, and evidence."}, {"id": "ddde8a75-a261-4633-a8ad-5090033f9088", "type": "subtopic", "title": "Evidence and scales of analysis", "children": [{"id": "e2d0b62e-0575-4c22-95eb-24f2e19dcad0", "type": "concept", "title": "Fossils and artifacts"}, {"id": "b16d3b3e-f636-497e-87f5-83eaed576c58", "type": "concept", "title": "Genes and populations"}, {"id": "3bb4198f-cde7-4ac3-9b13-ed6a6d7eb83d", "type": "concept", "title": "Behavior, ecology, and life history"}], "description": "This subtopic introduces the types of evidence used to study human evolution and variation."}, {"id": "61d75b7d-6f4a-4c49-946f-52635b7b83cf", "type": "subtopic", "title": "Scientific reasoning in human origins", "children": [{"id": "784e09e6-8856-4511-945c-8aa0f46beb0c", "type": "concept", "title": "Inference from incomplete evidence"}, {"id": "24e569ae-5fd1-41a1-8395-162599a4fb3e", "type": "concept", "title": "Multiple working hypotheses"}, {"id": "a58907df-4a3c-4f4d-9b31-2de1764f3259", "type": "concept", "title": "Uncertainty and peer review"}], "description": "Students learn how hypotheses about the past are built, tested, revised, and debated."}]}, {"id": "71be3305-01a6-42d6-89d6-b28b7867a8fe", "type": "topic", "title": "Evolutionary Theory and Natural Selection", "description": "Evolution is the foundation of biological anthropology. This unit gives students the core mechanisms needed to explain biological change without teleology or ladder-like thinking.", "children": [{"id": "8b2fe8e9-73a6-43ef-9de4-857cc57ec2d5", "type": "subtopic", "title": "Darwin, descent with modification, and selection", "children": [{"id": "a378bc7a-502f-4bf9-ac59-dacb1e1c26c5", "type": "concept", "title": "Variation and heritability"}, {"id": "3bb86cba-d372-461f-80fa-adafed6d02dc", "type": "concept", "title": "Fitness and reproductive success"}, {"id": "21d6365a-ecf3-4214-94d3-b03866b58d04", "type": "concept", "title": "Adaptation and constraint"}], "description": "Students learn how variation, inheritance, differential survival, and reproduction generate adaptation over time."}, {"id": "b7122dc2-9cc9-4e61-b97b-07d82a3663e2", "type": "subtopic", "title": "Mechanisms of evolution", "children": [{"id": "ead7ae87-e6dc-4e58-8e8d-6c7d37950513", "type": "concept", "title": "Mutation and recombination"}, {"id": "aea8d101-40d4-4182-8641-7170425672de", "type": "concept", "title": "Genetic drift and gene flow"}, {"id": "7801a675-4e44-4e42-a6f6-57d36f0231b3", "type": "concept", "title": "Sexual selection"}], "description": "This subtopic expands beyond natural selection to show how populations change."}, {"id": "6c9b7fe0-19b9-44cc-a527-18192f082d35", "type": "subtopic", "title": "Phylogeny and tree thinking", "children": [{"id": "ec3c6862-9045-46a6-949e-14e81a31af19", "type": "concept", "title": "Common ancestry"}, {"id": "096e4c41-c922-43f5-b66c-5328bb9c86d5", "type": "concept", "title": "Clades and outgroups"}, {"id": "efa688d2-bfc2-46aa-9ed7-49d39457f406", "type": "concept", "title": "Homology and analogy"}], "description": "Students learn to reason about relatedness using branching models rather than linear progress narratives."}]}, {"id": "82b9787a-138d-489d-a0a6-8fcd42cf9dd9", "type": "topic", "title": "Genetics, Inheritance, and Population Variation", "description": "Biological anthropology requires genetics at the level of individuals, families, and populations. This unit links molecular inheritance with evolutionary processes and human diversity.", "children": [{"id": "402014e5-add2-431c-941e-27cce66eb190", "type": "subtopic", "title": "Mendelian and molecular foundations", "children": [{"id": "71bfb191-6bfa-40f2-97eb-57213a644f5c", "type": "concept", "title": "DNA, genes, and alleles"}, {"id": "931b5ada-9b63-444b-9eb0-cf5048936317", "type": "concept", "title": "Mendelian inheritance"}, {"id": "7ab943a9-8dee-4138-941e-fc8377f0f28d", "type": "concept", "title": "Genotype and phenotype"}], "description": "Students review the inheritance concepts needed to understand traits and variation."}, {"id": "4b9eec4d-726f-4e95-b918-06ffd5bc2233", "type": "subtopic", "title": "Population genetics", "children": [{"id": "0b785896-b3a5-4eb8-bb69-173844e5cbd2", "type": "concept", "title": "Allele frequencies"}, {"id": "dec9b92d-346d-4ba2-a2ce-0af9db49c372", "type": "concept", "title": "Hardy-Weinberg equilibrium"}, {"id": "4785cda6-b315-4a87-98a2-20d60ac302b1", "type": "concept", "title": "Population structure"}], "description": "This subtopic introduces allele frequencies, Hardy-Weinberg expectations, and forces that shift genetic variation."}, {"id": "75e35c07-171d-4763-b277-0f69f4ed3515", "type": "subtopic", "title": "Human genetic diversity", "children": [{"id": "1cd2068c-fa99-48bb-a7fb-dbd2975a9dae", "type": "concept", "title": "Clines and gradients"}, {"id": "675faa8d-b7f0-4028-ac90-cbc664a4c869", "type": "concept", "title": "Founder effects"}, {"id": "c655cb26-3e09-4f78-924c-000ab74aaf20", "type": "concept", "title": "Admixture and ancestry inference"}], "description": "Students learn how variation is patterned by ancestry, migration, adaptation, drift, and gene flow."}]}, {"id": "54f600dc-86c1-4646-9857-8987b67b949b", "type": "topic", "title": "Primate Taxonomy, Ecology, and Behavior", "description": "Primates provide comparative context for understanding human evolution. This unit introduces primate diversity, social behavior, ecology, cognition, and conservation.", "children": [{"id": "26ef4564-db48-4132-a30f-2e9d644b944b", "type": "subtopic", "title": "Primate classification and traits", "children": [{"id": "e2e45812-7365-4b5e-b1df-503b39bad19f", "type": "concept", "title": "Strepsirrhines, tarsiers, monkeys, apes, and humans"}, {"id": "31b17eca-c0fd-4894-b475-edd5c7cb5dd2", "type": "concept", "title": "Grasping hands and vision"}, {"id": "a836c920-a311-4795-8dde-ce336fe350f6", "type": "concept", "title": "Brains, life history, and sociality"}], "description": "Students learn the major primate groups and the anatomical and behavioral traits that characterize them."}, {"id": "6bd4ba0b-1177-4953-95e8-becc4c2dc4ee", "type": "subtopic", "title": "Primate ecology and social systems", "children": [{"id": "552e6484-9e0b-454d-940f-df947687c88a", "type": "concept", "title": "Feeding ecology"}, {"id": "eb895bc9-eb56-462e-8233-0ad61a348626", "type": "concept", "title": "Mating systems"}, {"id": "5751e7b5-d19c-47b6-a192-5ae599378408", "type": "concept", "title": "Dominance, cooperation, and conflict"}], "description": "This subtopic connects diet, habitat, predation, reproduction, and group living."}, {"id": "fda7d03b-54bd-4717-a589-87c69563418f", "type": "subtopic", "title": "Primate cognition and conservation", "children": [{"id": "9bfcf37d-26bf-46c3-81d6-78d9685d2435", "type": "concept", "title": "Social learning"}, {"id": "ce0be309-7cab-4d11-bf8f-e74f3b49f627", "type": "concept", "title": "Tool use and communication"}, {"id": "a997ba4d-4ff2-42a4-bdd4-04d2562052fd", "type": "concept", "title": "Habitat loss and conservation ethics"}], "description": "Students examine tool use, communication, learning, culture-like behavior, and threats to primate survival."}]}, {"id": "c31e0ada-010d-4519-a4e9-54c4bed504d2", "type": "topic", "title": "Human Skeletal Anatomy and Osteology", "description": "Skeletal anatomy is a core evidence base for biological anthropology. Students learn how bones record locomotion, growth, sex, age, health, ancestry, trauma, and evolutionary history.", "children": [{"id": "ed26c963-e6e9-4654-ae42-d9e403a2ce9b", "type": "subtopic", "title": "The human skeleton", "children": [{"id": "fce58824-df38-459f-9c9d-46fb228fa796", "type": "concept", "title": "Axial and appendicular skeleton"}, {"id": "db42496d-2ea5-44c1-ad59-d923222c256e", "type": "concept", "title": "Landmarks and directional terms"}, {"id": "1858caaf-70b7-4b06-8b7d-dff65f16b3db", "type": "concept", "title": "Bone tissue and remodeling"}], "description": "Students learn major bones, anatomical terminology, and the relationship between form and function."}, {"id": "e72f73ad-499c-4baa-a940-1f9b3d7e9d11", "type": "subtopic", "title": "Functional anatomy", "children": [{"id": "8e76ffb8-4ba9-4601-8656-ab5e71729755", "type": "concept", "title": "Bipedal adaptations"}, {"id": "5c86ce93-b3b6-456f-ba58-02981db5dab4", "type": "concept", "title": "Dentition and chewing"}, {"id": "81618e07-f943-4241-9e72-e4221056ffbf", "type": "concept", "title": "Muscle attachments and activity"}], "description": "This subtopic links skeletal traits to locomotion, diet, growth, and biomechanics."}, {"id": "244b6952-7797-49b1-a3f8-c6a62b632ff6", "type": "subtopic", "title": "Skeletal variation and interpretation", "children": [{"id": "1d9d7aaf-d3f9-4d44-99e1-bc1b92384746", "type": "concept", "title": "Age and sex estimation"}, {"id": "326f8c3b-d09a-4041-8961-94d3d893503b", "type": "concept", "title": "Metric and nonmetric traits"}, {"id": "1539d2a1-2af0-4f8f-871d-96858eb3d24e", "type": "concept", "title": "Uncertainty and population reference samples"}], "description": "Students learn the limits and responsibilities of inferring identity or behavior from skeletal remains."}]}, {"id": "2e5346c2-6f44-4229-9560-3409861b70d9", "type": "topic", "title": "Fossilization, Dating, and Paleoanthropological Evidence", "description": "Human evolution is reconstructed from fragmentary traces preserved in geological context. This unit teaches students how paleoanthropologists build evidence from fossils, sites, sediments, dates, and comparative anatomy.", "children": [{"id": "e2fd6576-fdbc-48a0-9951-8cb42377fb8b", "type": "subtopic", "title": "Fossilization and site formation", "children": [{"id": "ceccecd7-ff4b-4f3b-bc35-894b6dc51368", "type": "concept", "title": "Taphonomy"}, {"id": "3e9e298b-338f-4872-9c86-57c455678bb0", "type": "concept", "title": "Preservation bias"}, {"id": "ee3eccf9-5fda-4222-bce1-ab9bf650fc80", "type": "concept", "title": "Depositional context"}], "description": "Students learn why fossil evidence is rare, biased, and context-dependent."}, {"id": "dd73d8e6-07fc-4f17-bebc-c80901deba2e", "type": "subtopic", "title": "Dating methods and chronology", "children": [{"id": "8caf61e7-6736-44d0-914e-cf6e454a730d", "type": "concept", "title": "Stratigraphy"}, {"id": "8e87b816-9341-4a3b-af20-7e5cc9a4b2d9", "type": "concept", "title": "Radiometric dating"}, {"id": "fdc70a09-ae68-4976-8487-4739e2883ac7", "type": "concept", "title": "Paleomagnetism and biostratigraphy"}], "description": "This subtopic introduces relative and absolute dating methods used to place fossils and artifacts in time."}, {"id": "ed7c185f-0f6f-4d02-b048-4a288876f9a2", "type": "subtopic", "title": "Comparative fossil analysis", "children": [{"id": "82349d95-816a-4a4e-9459-e0876ed6d271", "type": "concept", "title": "Cranial and dental traits"}, {"id": "f3fb9495-0380-4d02-a511-62187520cb6a", "type": "concept", "title": "Postcranial anatomy"}, {"id": "230598b4-7e0f-45e1-97fb-05f09d2f825a", "type": "concept", "title": "Mosaic evolution"}], "description": "Students practice reading fossil traits as evidence for evolutionary relationships and behavior."}]}, {"id": "eea09093-2da7-4334-9e29-93884b424309", "type": "topic", "title": "Early Hominins and the Evolution of Bipedalism", "description": "Bipedalism is one of the defining shifts in hominin evolution. This unit examines early hominins, environmental context, locomotor anatomy, and debates about why upright walking evolved.", "children": [{"id": "57880317-ce76-47c4-8404-66d04ee37479", "type": "subtopic", "title": "Defining hominins", "children": [{"id": "0a629717-bb6a-4d19-a554-3a2e722b7397", "type": "concept", "title": "Hominin versus hominoid"}, {"id": "16ddacad-8ef5-495a-ae96-78a97b074bf4", "type": "concept", "title": "Canine reduction"}, {"id": "5c799618-0921-4b9c-ac20-be8c8ca34694", "type": "concept", "title": "Bipedal indicators"}], "description": "Students learn how scientists identify early members of the human lineage."}, {"id": "a190deed-f016-47a0-9c07-39a0f02af397", "type": "subtopic", "title": "Key early hominin taxa", "children": [{"id": "105671eb-152f-420e-ab97-c75591065a04", "type": "concept", "title": "Sahelanthropus, Orrorin, and Ardipithecus"}, {"id": "6ce409b1-dbb2-4813-bc4e-903f97621437", "type": "concept", "title": "Australopithecus"}, {"id": "fa762105-0377-47bb-8fac-1e8c35b3c07b", "type": "concept", "title": "Paranthropus"}], "description": "This subtopic surveys major fossil groups and what they reveal."}, {"id": "9a469f87-b8f3-436b-9b64-ef04cca939da", "type": "subtopic", "title": "Bipedalism and environment", "children": [{"id": "9d2a9f25-cce6-451e-b88a-f3fe515f5b1f", "type": "concept", "title": "Pelvis, femur, foot, and spine"}, {"id": "a723b800-12ca-4e12-a667-ff352dd17525", "type": "concept", "title": "Savanna and woodland debates"}, {"id": "a7842f17-781a-4c0d-958d-cc1f11b55b77", "type": "concept", "title": "Costs and benefits of bipedality"}], "description": "Students evaluate hypotheses linking locomotion, ecology, energy, provisioning, and climate."}]}, {"id": "dff789f2-1b13-451f-a580-c8dd8e221d3e", "type": "topic", "title": "Genus Homo, Technology, and Pleistocene Dispersals", "description": "This unit follows the emergence of Homo and the expansion of hominins across Africa and Eurasia. Students connect anatomy, brains, tools, diet, cooperation, and changing environments.", "children": [{"id": "e7cb8735-fd70-4405-91e4-911594f16e47", "type": "subtopic", "title": "Early Homo and adaptive shifts", "children": [{"id": "639fa854-2365-4e0f-88f3-bf14e45fd6f6", "type": "concept", "title": "Brain and body size"}, {"id": "46672609-1339-4285-a5f9-16f7e3ca006d", "type": "concept", "title": "Diet and foraging"}, {"id": "c6d41018-8c2d-45c6-8f59-f5d3ce4109dd", "type": "concept", "title": "Oldowan technology"}], "description": "Students examine anatomical and behavioral changes associated with early Homo."}, {"id": "157aa12a-97f2-482c-a8dd-7b20173b71c3", "type": "subtopic", "title": "Homo erectus and dispersal", "children": [{"id": "a65bfe9f-dc59-450e-8090-d0a457482e16", "type": "concept", "title": "Out of Africa I"}, {"id": "3012f606-2602-4d60-8537-971fde341bc8", "type": "concept", "title": "Acheulean handaxes"}, {"id": "36d0f3af-7615-4d56-b469-a73500d7cf64", "type": "concept", "title": "Fire and ranging behavior"}], "description": "This subtopic studies long-distance movement, Acheulean tools, endurance, and ecological flexibility."}, {"id": "25348c85-a9f7-4aa1-b7b8-bd2ba3066933", "type": "subtopic", "title": "Pleistocene variability", "children": [{"id": "cf4fafdd-3354-41c7-9e9b-4439e8729c00", "type": "concept", "title": "Regional populations"}, {"id": "ff53cb74-4046-4fb5-9208-9e761332afef", "type": "concept", "title": "Climate cycles"}, {"id": "17cb0d24-e7ea-4fbe-9e7d-434fc62c20ce", "type": "concept", "title": "Species debates"}], "description": "Students learn that Homo evolution was branching, regional, and diverse rather than linear."}]}, {"id": "afac4d4b-2ab1-476d-a179-0f92cc654827", "type": "topic", "title": "Neanderthals, Denisovans, Ancient DNA, and Admixture", "description": "Ancient DNA has transformed human origins research. This unit examines late archaic humans, interbreeding, adaptation, extinction, and how genetic evidence changes fossil interpretation.", "children": [{"id": "646ccba8-aeb6-4205-8684-84640da67345", "type": "subtopic", "title": "Neanderthal biology and behavior", "children": [{"id": "f6f750fb-c59e-418c-98e7-829030380880", "type": "concept", "title": "Cold adaptation"}, {"id": "bd9a1b91-5b04-404b-aff4-75e4ded4a4e6", "type": "concept", "title": "Mousterian technology"}, {"id": "9437efa3-24f7-421e-af67-5afaad20e569", "type": "concept", "title": "Burial and symbolic behavior"}], "description": "Students examine Neanderthal anatomy, ecology, tools, care, symbolism, and debates about cognition."}, {"id": "28730ce2-c81a-4d6c-a9c2-71dd89812e73", "type": "subtopic", "title": "Denisovans and other archaic populations", "children": [{"id": "3f8bbd64-01cb-48c1-95ea-8189f27ff40a", "type": "concept", "title": "Denisovan DNA"}, {"id": "c8667ed7-fe56-4d60-9f78-d8a3a2bd1629", "type": "concept", "title": "Asian and Oceanian ancestry"}, {"id": "6971e17b-0ec8-4d3f-8e3f-884d1986720a", "type": "concept", "title": "Ghost populations"}], "description": "This subtopic introduces genetic lineages known from limited fossil evidence."}, {"id": "f5f920bd-43ba-4564-b45b-200e9b377eb3", "type": "subtopic", "title": "Ancient DNA and admixture", "children": [{"id": "71126136-ef1f-4b0f-968d-7be70706edaa", "type": "concept", "title": "Introgression"}, {"id": "4beab602-e552-458f-9f68-32a6272e93f9", "type": "concept", "title": "Adaptive variants"}, {"id": "72beb0d0-aab4-44af-8869-1803bc2f0d10", "type": "concept", "title": "Contamination and consent"}], "description": "Students learn how genomes reveal interbreeding and adaptation while raising ethical and interpretive questions."}]}, {"id": "e4eaef38-a8d3-4260-8d7b-f73c824ddbf6", "type": "topic", "title": "Modern Human Origins, Culture, and Symbolic Behavior", "description": "This unit examines the emergence and dispersal of Homo sapiens, emphasizing the interaction of biology, behavior, ecology, and culture. Students learn how modernity is debated through multiple lines of evidence.", "children": [{"id": "a52ae863-29c8-448c-a9f4-7a242bd64f77", "type": "subtopic", "title": "Origins of Homo sapiens", "children": [{"id": "0ceb7a9f-e144-40d2-a803-19c056c6271b", "type": "concept", "title": "African origins"}, {"id": "0e1c01de-76a1-4d4f-b03b-da2b7bccf33a", "type": "concept", "title": "Population structure"}, {"id": "f6497a07-d1a8-47f7-bf03-ec2e891716bc", "type": "concept", "title": "Out of Africa II"}], "description": "Students compare fossil, genetic, and archaeological evidence for modern human origins."}, {"id": "45561f88-4f5c-4394-aa50-0f4ce371dbc8", "type": "subtopic", "title": "Behavioral complexity", "children": [{"id": "b4a3692b-fbed-4c63-a0b3-3249517f7ed8", "type": "concept", "title": "Middle Stone Age innovations"}, {"id": "77e2d0f8-baae-4e89-949b-e8e9d4c1eda2", "type": "concept", "title": "Symbolic artifacts"}, {"id": "19e6a278-fe5a-441e-b754-598d3078e0cd", "type": "concept", "title": "Language and social learning"}], "description": "This subtopic examines tools, art, ornaments, burials, long-distance exchange, and symbolic communication."}, {"id": "2ce6dc6f-ae89-474b-810d-8deb99d73219", "type": "subtopic", "title": "Migration and adaptation", "children": [{"id": "3ba1d682-ea3d-4f5e-85ea-7a312c8493ab", "type": "concept", "title": "Coastal and inland routes"}, {"id": "c0ef85f0-335c-43e8-a5b1-7eaa2aaab0cd", "type": "concept", "title": "Sahul and the Americas"}, {"id": "6d4018c1-c0a3-4b05-8901-214e76571fc8", "type": "concept", "title": "Local adaptation"}], "description": "Students connect dispersal with climate, ecology, technology, and population contact."}]}, {"id": "6b8bcbe1-69ee-4afe-b80c-97155239d779", "type": "topic", "title": "Human Biological Variation and the Critique of Race", "description": "Biological anthropology has a responsibility to explain human variation accurately and challenge racial typologies. This unit teaches students why race is not a valid biological taxonomy while racism has real biological consequences.", "children": [{"id": "6bf79ee0-c7c4-4cf4-8683-a870a7abcd39", "type": "subtopic", "title": "Patterns of human variation", "children": [{"id": "47e4e2d4-896a-4174-86df-76d88bfdc3d3", "type": "concept", "title": "Clines"}, {"id": "1b6ef3ee-371f-495a-b363-45d22e334b37", "type": "concept", "title": "Within-group variation"}, {"id": "1ef2fc51-a2f4-4c7b-8123-62bc358cfb68", "type": "concept", "title": "Gene flow and migration"}], "description": "Students learn that human traits vary clinally, historically, and adaptively rather than as bounded races."}, {"id": "827e8e84-aa14-4882-b43f-ddfbc5ec763a", "type": "subtopic", "title": "Race, racism, and biology", "children": [{"id": "f607ac56-8a23-4ccd-93ec-1cf9c5dfe51f", "type": "concept", "title": "Race as social classification"}, {"id": "d652ae94-54d2-46f1-94fb-8217e574f297", "type": "concept", "title": "Ancestry versus race"}, {"id": "f1dad751-5e86-4e20-8de1-ae700f21968e", "type": "concept", "title": "Embodiment of inequality"}], "description": "This subtopic distinguishes social race from biological ancestry and examines the health effects of racism."}, {"id": "fe87a0e6-7fe4-45ac-acd0-fad047fca24a", "type": "subtopic", "title": "Communicating variation responsibly", "children": [{"id": "40e7b888-6781-4dcd-8b5d-89f4eba34d17", "type": "concept", "title": "Trait complexity"}, {"id": "4c2eb080-600d-4740-bd8d-f11071dbfb0f", "type": "concept", "title": "Population labels"}, {"id": "aeb9ad6d-8eba-4c74-a31d-414f6a56475e", "type": "concept", "title": "Ethical communication"}], "description": "Students practice avoiding genetic determinism, typological thinking, and misuse of ancestry data."}]}, {"id": "4d50ffe3-7eb5-4c5c-92b6-8fc13a371cc0", "type": "topic", "title": "Human Adaptation: Climate, Diet, Disease, and Altitude", "description": "Humans adapt biologically and culturally to diverse environments. This unit examines thermoregulation, nutrition, disease ecology, altitude, skin pigmentation, and gene-culture coevolution.", "children": [{"id": "8cc82432-714e-4d8f-9aa2-d66c71706c3d", "type": "subtopic", "title": "Climate and body form", "children": [{"id": "bedbdd3e-bd9b-4d05-852f-1a9c98e91983", "type": "concept", "title": "Bergmann's and Allen's rules"}, {"id": "da52d376-89ec-4813-9615-8544af782f96", "type": "concept", "title": "Heat and cold stress"}, {"id": "ac8ee9f9-6dea-43b9-881e-d211789ae7c4", "type": "concept", "title": "Plasticity and acclimatization"}], "description": "Students learn how body size, limb proportions, and physiology relate to thermal environments."}, {"id": "6eb8c5e3-3053-4400-9568-92af1c9ec214", "type": "subtopic", "title": "Diet and gene-culture coevolution", "children": [{"id": "b1da52da-acac-4f69-9887-a7636f813117", "type": "concept", "title": "Lactase persistence"}, {"id": "bd4e5ee2-a73b-4423-ae2d-0a744b605e2e", "type": "concept", "title": "Amylase variation"}, {"id": "13651612-c50c-42c3-8e05-5f5eb3315895", "type": "concept", "title": "Agriculture and selection"}], "description": "This subtopic connects subsistence, agriculture, lactose digestion, starch digestion, and microbiomes."}, {"id": "3dbbcc16-bded-42e9-9146-628afd40c186", "type": "subtopic", "title": "Disease and altitude adaptation", "children": [{"id": "7b4ac502-2cd7-4916-8b13-08fd6dda63ee", "type": "concept", "title": "Balanced polymorphism"}, {"id": "b8aef18f-7393-40ed-a2d5-186e2d8c50ba", "type": "concept", "title": "Hypoxia adaptation"}, {"id": "1d7d78bd-32fb-46cb-9776-5ddaaf3bcd1c", "type": "concept", "title": "Pathogens and selection"}], "description": "Students study malaria, sickle-cell traits, immune variation, and high-altitude physiology."}]}, {"id": "3da9b89b-2ea1-45ad-b1b5-f2bda5fe85b8", "type": "topic", "title": "Life History, Growth, Development, and Reproduction", "description": "Human bodies are shaped across the life course. This unit examines growth, childhood, adolescence, reproduction, aging, and the evolutionary tradeoffs that make human life history distinctive.", "children": [{"id": "983baa89-2815-4270-8f40-287af8b0cca4", "type": "subtopic", "title": "Human growth and development", "children": [{"id": "7654db15-de41-465f-9db3-8fe013016781", "type": "concept", "title": "Growth curves"}, {"id": "f6e5763d-43f7-4a1c-9214-1263622974a8", "type": "concept", "title": "Developmental plasticity"}, {"id": "6f83b3f7-fd8d-4d0d-83a0-2fbf3124ae8f", "type": "concept", "title": "Stress and nutrition"}], "description": "Students learn how biology, nutrition, stress, culture, and environment shape development."}, {"id": "7fe2cb07-4145-4e60-ae8c-b4395c18ccab", "type": "subtopic", "title": "Reproductive ecology", "children": [{"id": "5193a67f-8b3b-4cc9-82e1-a076ebe44f48", "type": "concept", "title": "Energetics and fertility"}, {"id": "af89817a-4d53-4c09-bbc0-95332048dc39", "type": "concept", "title": "Parental investment"}, {"id": "c3791fff-f38c-40cc-9f18-2ed9d630df66", "type": "concept", "title": "Alloparenting"}], "description": "This subtopic introduces fertility, parental investment, cooperative breeding, and reproductive tradeoffs."}, {"id": "cd659319-1a01-4b4e-95f5-94e933503b72", "type": "subtopic", "title": "Aging and life history", "children": [{"id": "6282ae31-3de1-4fbd-bccd-c81072536427", "type": "concept", "title": "Life-history tradeoffs"}, {"id": "0be9ce46-6d1b-4635-af93-e049f7ae5f02", "type": "concept", "title": "Grandmother hypothesis"}, {"id": "a1c74d90-76e1-464c-ae55-06594542555a", "type": "concept", "title": "Aging and social support"}], "description": "Students examine longevity, grandparents, menopause, senescence, and intergenerational support."}]}, {"id": "1e988e5e-4ea4-4fb6-8b6f-7fd605a182b7", "type": "topic", "title": "Bioarchaeology: Reconstructing Lives from Human Remains", "description": "Bioarchaeology uses skeletal and contextual evidence to reconstruct health, diet, labor, violence, migration, and inequality in past populations. Students learn how bones become social evidence.", "children": [{"id": "1cd95439-ca61-4313-8d34-c032a0ff861c", "type": "subtopic", "title": "Paleopathology and health", "children": [{"id": "4a55b093-eac9-4dc7-832f-6520deb9ad28", "type": "concept", "title": "Stress markers"}, {"id": "abf5a70e-bad5-4529-959c-3e5e829df6b0", "type": "concept", "title": "Trauma and fracture"}, {"id": "6d9dd418-3531-4ff2-913c-082121268e73", "type": "concept", "title": "Infectious and degenerative disease"}], "description": "Students learn how disease, trauma, stress, and nutrition can leave skeletal traces."}, {"id": "5ee2beca-c93b-420c-bf5e-451622ced4f3", "type": "subtopic", "title": "Diet, mobility, and isotopes", "children": [{"id": "963d3efe-fe0a-4825-9772-a90f1999e938", "type": "concept", "title": "Stable isotopes"}, {"id": "f20468d4-4148-4983-8d60-08f0c86988d1", "type": "concept", "title": "Strontium and oxygen"}, {"id": "36c35ea3-a652-4630-ba0e-dfa05e2b5e57", "type": "concept", "title": "Dental calculus and residues"}], "description": "This subtopic introduces chemical methods for reconstructing past lives."}, {"id": "1305b23a-b99f-4d08-ba2a-3850b38d411a", "type": "subtopic", "title": "Population and social context", "children": [{"id": "4b2185c3-ab33-4aa4-93e3-f4e460d7522e", "type": "concept", "title": "Mortuary context"}, {"id": "3e5cfdf5-3b13-4df5-ac12-438a3a78205d", "type": "concept", "title": "Activity patterns"}, {"id": "892eb3df-d567-4e4a-b9a0-3ae24b4c6f40", "type": "concept", "title": "Population-level interpretation"}], "description": "Students connect skeletal patterns with archaeology, history, environment, and inequality."}]}, {"id": "6a11a868-df09-41d0-8821-3d4ae0df162a", "type": "topic", "title": "Forensic Anthropology and Human Identification", "description": "Forensic anthropology applies skeletal expertise to legal and humanitarian contexts. This unit introduces methods of identification while emphasizing uncertainty, ethics, and the limits of biological profiles.", "children": [{"id": "2fec0e0c-1b22-40b4-b8eb-cf8bd78d3c95", "type": "subtopic", "title": "Forensic context and recovery", "children": [{"id": "51ac3a9c-ea62-4229-b237-bcb73283f1c5", "type": "concept", "title": "Search and recovery"}, {"id": "620259c1-ce84-4b7f-a59b-8346860671f6", "type": "concept", "title": "Chain of custody"}, {"id": "177f9ad7-b375-46ca-96a5-c849e884b106", "type": "concept", "title": "Postmortem interval"}], "description": "Students learn how scene recovery, chain of custody, taphonomy, and documentation shape forensic analysis."}, {"id": "6066dcca-ffe1-4f61-9af3-456dd1087cd9", "type": "subtopic", "title": "Biological profile", "children": [{"id": "984e3e68-db26-497a-bf76-aa8fdcabdf3b", "type": "concept", "title": "Age and sex estimation"}, {"id": "7aeefb48-9cab-48f3-83f7-25f221e9cc08", "type": "concept", "title": "Stature and ancestry estimation"}, {"id": "fc85e7ba-c4e3-48fc-9623-075751e43f09", "type": "concept", "title": "Antemortem and perimortem trauma"}], "description": "This subtopic introduces estimation of age, sex, ancestry, stature, trauma, and individualizing features."}, {"id": "58e13494-e911-4eab-85e4-ba8e7bdff85c", "type": "subtopic", "title": "Human rights and disaster contexts", "children": [{"id": "f773b0a0-58fd-45f2-b4a6-4703641f63fe", "type": "concept", "title": "Humanitarian forensics"}, {"id": "227e9266-6f72-403d-9e0f-9caf44420215", "type": "concept", "title": "Mass graves"}, {"id": "d50ab1f8-0f82-43d2-8909-e3a8ce578650", "type": "concept", "title": "Family and community accountability"}], "description": "Students examine forensic anthropology in mass disasters, missing persons, war crimes, and migrant death investigations."}]}, {"id": "cccf68f0-124d-46fa-8f9b-3e22f7c8ab20", "type": "topic", "title": "Evolutionary Medicine and Human Health", "description": "Evolutionary medicine uses evolutionary theory to explain vulnerability, adaptation, mismatch, and disease. This unit shows how biological anthropology can inform contemporary health without reducing health to genes.", "children": [{"id": "3c49ce06-e95c-45d1-ae9a-1f747fe69920", "type": "subtopic", "title": "Mismatch and modern environments", "children": [{"id": "af070d4c-b06f-4ebf-b616-2b045b09ee46", "type": "concept", "title": "Thrifty genotype and phenotype debates"}, {"id": "87520972-96d0-4d03-8b13-6012d1ea89a8", "type": "concept", "title": "Sedentism and diet"}, {"id": "6f68307f-442e-415a-81d9-ae3d2fbb9502", "type": "concept", "title": "Sleep, stress, and urban life"}], "description": "Students examine how evolved traits interact with rapid changes in diet, activity, pathogens, and built environments."}, {"id": "eeec29c4-51c5-44cc-9c18-aedc8fad4dd4", "type": "subtopic", "title": "Pathogens, immunity, and evolution", "children": [{"id": "cc76ef6d-7a58-4ae9-8df1-e128ccac07e9", "type": "concept", "title": "Host-pathogen coevolution"}, {"id": "fe84c821-dfe4-42b0-a793-f276c64b2461", "type": "concept", "title": "Microbiome diversity"}, {"id": "17bab297-d81e-4fdb-aa9d-193a9a23af55", "type": "concept", "title": "Antibiotic resistance"}], "description": "This subtopic connects infectious disease, immune variation, microbiomes, and coevolution."}, {"id": "e3fd4236-8d7a-4061-a9a7-a453c0593ca9", "type": "subtopic", "title": "Biocultural health", "children": [{"id": "ed6eea8c-1183-4cff-943c-9c924a4928bd", "type": "concept", "title": "Embodiment"}, {"id": "da706949-fe95-4e41-aca0-5d3bfb3805fd", "type": "concept", "title": "Structural violence"}, {"id": "ec7bb43a-ce9a-4538-9e16-01b8def27593", "type": "concept", "title": "Health disparities"}], "description": "Students learn to integrate biology, culture, political economy, inequality, and lived environments."}]}, {"id": "5e47ab25-b803-4be2-b1df-bd05d684b511", "type": "topic", "title": "Ethics, Repatriation, Community Collaboration, and Public Anthropology", "description": "Biological anthropology works with human remains, living communities, genetic data, and sensitive histories. This unit centers consent, repatriation, descendant communities, anti-racism, and public communication.", "children": [{"id": "7f530a89-9a7e-4979-9867-5543db5b5e93", "type": "subtopic", "title": "Ethics of human remains", "children": [{"id": "37c1cd00-ff66-414b-86e7-ff7ca7bbc190", "type": "concept", "title": "Respect and dignity"}, {"id": "3e626e19-8477-49d0-b5c3-d02585609aaf", "type": "concept", "title": "Consent and permissions"}, {"id": "3a76cffc-49ea-495c-9d4e-bb7119cef4d6", "type": "concept", "title": "Curation and access"}], "description": "Students learn why excavation, storage, display, teaching, and research on remains require special responsibility."}, {"id": "519eaf20-7add-4a4b-abf5-f29a839e074c", "type": "subtopic", "title": "Repatriation and descendant communities", "children": [{"id": "c91d720e-30cd-40ed-92d8-fdac9a4d4823", "type": "concept", "title": "NAGPRA and repatriation"}, {"id": "852ba1c1-57f9-4802-b824-e27df12ef792", "type": "concept", "title": "Community consultation"}, {"id": "8fffafd3-324b-4180-9130-57528465697e", "type": "concept", "title": "Collaborative research"}], "description": "This subtopic examines legal and ethical obligations to Indigenous and descendant communities."}, {"id": "5279957f-4292-46b6-9aec-dc585e3e8272", "type": "subtopic", "title": "Public communication and misuse", "children": [{"id": "16ba0749-2efb-4706-8207-1ff7217f10d2", "type": "concept", "title": "Anti-racist science communication"}, {"id": "0fb84daf-f29b-4ae4-83ce-3339330318ae", "type": "concept", "title": "Combatting pseudoscience"}, {"id": "217c9ac6-40e6-4ddf-b7d3-7e90072c989f", "type": "concept", "title": "Public trust and transparency"}], "description": "Students practice communicating evolution, variation, ancestry, and fossils responsibly."}]}, {"id": "4ee1ca8c-cc0c-4728-a510-ee9d953e912d", "type": "topic", "title": "Capstone: Human Evolution Evidence Portfolio", "description": "The course culminates in a project where students synthesize fossils, genetics, primatology, skeletal evidence, ethics, and public communication. The goal is to reason like a biological anthropologist with multiple forms of evidence.", "children": [{"id": "2c6cd1b6-be84-4eb7-bd5e-4ba6ddef098e", "type": "subtopic", "title": "Research question and evidence map", "children": [{"id": "b224f6de-8ab1-4b94-a342-fa89caf8afd2", "type": "concept", "title": "Question design"}, {"id": "9bd16c93-0faa-43b6-ada9-cb1b301ee40c", "type": "concept", "title": "Evidence types"}, {"id": "639d23dc-4375-489e-a0d0-aee0e8d97015", "type": "concept", "title": "Competing hypotheses"}], "description": "Students define a focused question and identify the evidence needed to answer it."}, {"id": "b0b08848-e46e-4a13-86ce-d365972db200", "type": "subtopic", "title": "Analysis and interpretation", "children": [{"id": "e686e483-9d1b-425d-a0e7-4d6514bde222", "type": "concept", "title": "Trait comparison"}, {"id": "7c0c66f7-b548-4d31-be6e-65fdf57c9d01", "type": "concept", "title": "Data quality"}, {"id": "81a080ad-1a83-45f0-8708-91cfa10f0ba9", "type": "concept", "title": "Uncertainty and limits"}], "description": "This subtopic guides students through evaluating fossil, genetic, comparative, or skeletal evidence."}, {"id": "17a52982-c116-4005-a552-ebe0dc2229e8", "type": "subtopic", "title": "Public-facing synthesis", "children": [{"id": "16f28412-62ef-4d6f-b4c5-4a8f5aa24c4c", "type": "concept", "title": "Clear explanation"}, {"id": "a0f899ba-843b-45b7-a39c-8a590acd1bf4", "type": "concept", "title": "Ethical caveats"}, {"id": "7c171f04-f7d4-4fa9-b00b-946f30e7b419", "type": "concept", "title": "Visual or public communication"}], "description": "Students translate their findings into a short paper, exhibit text, poster, or digital brief."}]}], "dbBacked": true}$bpanjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'biological-physical-anthropology'
);

update public.learning_paths
set
  title = 'Biological / Physical Anthropology',
  goal = 'Biological / Physical Anthropology',
  summary = 'Biological / Physical Anthropology introduces human evolution and biological diversity through evolutionary theory, genetics, primatology, skeletal anatomy, paleoanthropology, bioarchaeology, forensics, adaptation, and ethics. The course emphasizes scientific reasoning, multiple lines of evidence, anti-racist communication about human variation, and respectful work with human remains and descendant communities.',
  data = $bpanjson${"slug": "biological-physical-anthropology", "title": "Biological / Physical Anthropology", "description": "Biological / Physical Anthropology introduces human evolution and biological diversity through evolutionary theory, genetics, primatology, skeletal anatomy, paleoanthropology, bioarchaeology, forensics, adaptation, and ethics. The course emphasizes scientific reasoning, multiple lines of evidence, anti-racist communication about human variation, and respectful work with human remains and descendant communities.", "topics": [{"id": "91d29025-e976-4d62-8050-e6e64c266de9", "type": "topic", "title": "Biological Anthropology as Evolutionary Human Science", "description": "This opening unit frames biological anthropology as the study of humans and our relatives through evolution, biology, behavior, ecology, fossils, genetics, and culture. Students learn how the field connects natural science with anthropological questions about human diversity and origins.", "children": [{"id": "35f58221-ed63-4507-9237-1602a36ab93f", "type": "subtopic", "title": "Four-field anthropology and biological anthropology", "children": [{"id": "ee11ea43-464e-4765-b2f1-32c99e806846", "type": "concept", "title": "Cultural, archaeological, linguistic, and biological anthropology"}, {"id": "92c2688c-1bcf-4ef2-9b17-92c7f220299f", "type": "concept", "title": "Human biology in cultural context"}, {"id": "17b3eae2-b975-45a1-b6ad-804a877c2dd8", "type": "concept", "title": "Holism and comparison"}], "description": "Students locate biological anthropology within anthropology's broader concern with human beings across time, place, and evidence."}, {"id": "ddde8a75-a261-4633-a8ad-5090033f9088", "type": "subtopic", "title": "Evidence and scales of analysis", "children": [{"id": "e2d0b62e-0575-4c22-95eb-24f2e19dcad0", "type": "concept", "title": "Fossils and artifacts"}, {"id": "b16d3b3e-f636-497e-87f5-83eaed576c58", "type": "concept", "title": "Genes and populations"}, {"id": "3bb4198f-cde7-4ac3-9b13-ed6a6d7eb83d", "type": "concept", "title": "Behavior, ecology, and life history"}], "description": "This subtopic introduces the types of evidence used to study human evolution and variation."}, {"id": "61d75b7d-6f4a-4c49-946f-52635b7b83cf", "type": "subtopic", "title": "Scientific reasoning in human origins", "children": [{"id": "784e09e6-8856-4511-945c-8aa0f46beb0c", "type": "concept", "title": "Inference from incomplete evidence"}, {"id": "24e569ae-5fd1-41a1-8395-162599a4fb3e", "type": "concept", "title": "Multiple working hypotheses"}, {"id": "a58907df-4a3c-4f4d-9b31-2de1764f3259", "type": "concept", "title": "Uncertainty and peer review"}], "description": "Students learn how hypotheses about the past are built, tested, revised, and debated."}]}, {"id": "71be3305-01a6-42d6-89d6-b28b7867a8fe", "type": "topic", "title": "Evolutionary Theory and Natural Selection", "description": "Evolution is the foundation of biological anthropology. This unit gives students the core mechanisms needed to explain biological change without teleology or ladder-like thinking.", "children": [{"id": "8b2fe8e9-73a6-43ef-9de4-857cc57ec2d5", "type": "subtopic", "title": "Darwin, descent with modification, and selection", "children": [{"id": "a378bc7a-502f-4bf9-ac59-dacb1e1c26c5", "type": "concept", "title": "Variation and heritability"}, {"id": "3bb86cba-d372-461f-80fa-adafed6d02dc", "type": "concept", "title": "Fitness and reproductive success"}, {"id": "21d6365a-ecf3-4214-94d3-b03866b58d04", "type": "concept", "title": "Adaptation and constraint"}], "description": "Students learn how variation, inheritance, differential survival, and reproduction generate adaptation over time."}, {"id": "b7122dc2-9cc9-4e61-b97b-07d82a3663e2", "type": "subtopic", "title": "Mechanisms of evolution", "children": [{"id": "ead7ae87-e6dc-4e58-8e8d-6c7d37950513", "type": "concept", "title": "Mutation and recombination"}, {"id": "aea8d101-40d4-4182-8641-7170425672de", "type": "concept", "title": "Genetic drift and gene flow"}, {"id": "7801a675-4e44-4e42-a6f6-57d36f0231b3", "type": "concept", "title": "Sexual selection"}], "description": "This subtopic expands beyond natural selection to show how populations change."}, {"id": "6c9b7fe0-19b9-44cc-a527-18192f082d35", "type": "subtopic", "title": "Phylogeny and tree thinking", "children": [{"id": "ec3c6862-9045-46a6-949e-14e81a31af19", "type": "concept", "title": "Common ancestry"}, {"id": "096e4c41-c922-43f5-b66c-5328bb9c86d5", "type": "concept", "title": "Clades and outgroups"}, {"id": "efa688d2-bfc2-46aa-9ed7-49d39457f406", "type": "concept", "title": "Homology and analogy"}], "description": "Students learn to reason about relatedness using branching models rather than linear progress narratives."}]}, {"id": "82b9787a-138d-489d-a0a6-8fcd42cf9dd9", "type": "topic", "title": "Genetics, Inheritance, and Population Variation", "description": "Biological anthropology requires genetics at the level of individuals, families, and populations. This unit links molecular inheritance with evolutionary processes and human diversity.", "children": [{"id": "402014e5-add2-431c-941e-27cce66eb190", "type": "subtopic", "title": "Mendelian and molecular foundations", "children": [{"id": "71bfb191-6bfa-40f2-97eb-57213a644f5c", "type": "concept", "title": "DNA, genes, and alleles"}, {"id": "931b5ada-9b63-444b-9eb0-cf5048936317", "type": "concept", "title": "Mendelian inheritance"}, {"id": "7ab943a9-8dee-4138-941e-fc8377f0f28d", "type": "concept", "title": "Genotype and phenotype"}], "description": "Students review the inheritance concepts needed to understand traits and variation."}, {"id": "4b9eec4d-726f-4e95-b918-06ffd5bc2233", "type": "subtopic", "title": "Population genetics", "children": [{"id": "0b785896-b3a5-4eb8-bb69-173844e5cbd2", "type": "concept", "title": "Allele frequencies"}, {"id": "dec9b92d-346d-4ba2-a2ce-0af9db49c372", "type": "concept", "title": "Hardy-Weinberg equilibrium"}, {"id": "4785cda6-b315-4a87-98a2-20d60ac302b1", "type": "concept", "title": "Population structure"}], "description": "This subtopic introduces allele frequencies, Hardy-Weinberg expectations, and forces that shift genetic variation."}, {"id": "75e35c07-171d-4763-b277-0f69f4ed3515", "type": "subtopic", "title": "Human genetic diversity", "children": [{"id": "1cd2068c-fa99-48bb-a7fb-dbd2975a9dae", "type": "concept", "title": "Clines and gradients"}, {"id": "675faa8d-b7f0-4028-ac90-cbc664a4c869", "type": "concept", "title": "Founder effects"}, {"id": "c655cb26-3e09-4f78-924c-000ab74aaf20", "type": "concept", "title": "Admixture and ancestry inference"}], "description": "Students learn how variation is patterned by ancestry, migration, adaptation, drift, and gene flow."}]}, {"id": "54f600dc-86c1-4646-9857-8987b67b949b", "type": "topic", "title": "Primate Taxonomy, Ecology, and Behavior", "description": "Primates provide comparative context for understanding human evolution. This unit introduces primate diversity, social behavior, ecology, cognition, and conservation.", "children": [{"id": "26ef4564-db48-4132-a30f-2e9d644b944b", "type": "subtopic", "title": "Primate classification and traits", "children": [{"id": "e2e45812-7365-4b5e-b1df-503b39bad19f", "type": "concept", "title": "Strepsirrhines, tarsiers, monkeys, apes, and humans"}, {"id": "31b17eca-c0fd-4894-b475-edd5c7cb5dd2", "type": "concept", "title": "Grasping hands and vision"}, {"id": "a836c920-a311-4795-8dde-ce336fe350f6", "type": "concept", "title": "Brains, life history, and sociality"}], "description": "Students learn the major primate groups and the anatomical and behavioral traits that characterize them."}, {"id": "6bd4ba0b-1177-4953-95e8-becc4c2dc4ee", "type": "subtopic", "title": "Primate ecology and social systems", "children": [{"id": "552e6484-9e0b-454d-940f-df947687c88a", "type": "concept", "title": "Feeding ecology"}, {"id": "eb895bc9-eb56-462e-8233-0ad61a348626", "type": "concept", "title": "Mating systems"}, {"id": "5751e7b5-d19c-47b6-a192-5ae599378408", "type": "concept", "title": "Dominance, cooperation, and conflict"}], "description": "This subtopic connects diet, habitat, predation, reproduction, and group living."}, {"id": "fda7d03b-54bd-4717-a589-87c69563418f", "type": "subtopic", "title": "Primate cognition and conservation", "children": [{"id": "9bfcf37d-26bf-46c3-81d6-78d9685d2435", "type": "concept", "title": "Social learning"}, {"id": "ce0be309-7cab-4d11-bf8f-e74f3b49f627", "type": "concept", "title": "Tool use and communication"}, {"id": "a997ba4d-4ff2-42a4-bdd4-04d2562052fd", "type": "concept", "title": "Habitat loss and conservation ethics"}], "description": "Students examine tool use, communication, learning, culture-like behavior, and threats to primate survival."}]}, {"id": "c31e0ada-010d-4519-a4e9-54c4bed504d2", "type": "topic", "title": "Human Skeletal Anatomy and Osteology", "description": "Skeletal anatomy is a core evidence base for biological anthropology. Students learn how bones record locomotion, growth, sex, age, health, ancestry, trauma, and evolutionary history.", "children": [{"id": "ed26c963-e6e9-4654-ae42-d9e403a2ce9b", "type": "subtopic", "title": "The human skeleton", "children": [{"id": "fce58824-df38-459f-9c9d-46fb228fa796", "type": "concept", "title": "Axial and appendicular skeleton"}, {"id": "db42496d-2ea5-44c1-ad59-d923222c256e", "type": "concept", "title": "Landmarks and directional terms"}, {"id": "1858caaf-70b7-4b06-8b7d-dff65f16b3db", "type": "concept", "title": "Bone tissue and remodeling"}], "description": "Students learn major bones, anatomical terminology, and the relationship between form and function."}, {"id": "e72f73ad-499c-4baa-a940-1f9b3d7e9d11", "type": "subtopic", "title": "Functional anatomy", "children": [{"id": "8e76ffb8-4ba9-4601-8656-ab5e71729755", "type": "concept", "title": "Bipedal adaptations"}, {"id": "5c86ce93-b3b6-456f-ba58-02981db5dab4", "type": "concept", "title": "Dentition and chewing"}, {"id": "81618e07-f943-4241-9e72-e4221056ffbf", "type": "concept", "title": "Muscle attachments and activity"}], "description": "This subtopic links skeletal traits to locomotion, diet, growth, and biomechanics."}, {"id": "244b6952-7797-49b1-a3f8-c6a62b632ff6", "type": "subtopic", "title": "Skeletal variation and interpretation", "children": [{"id": "1d9d7aaf-d3f9-4d44-99e1-bc1b92384746", "type": "concept", "title": "Age and sex estimation"}, {"id": "326f8c3b-d09a-4041-8961-94d3d893503b", "type": "concept", "title": "Metric and nonmetric traits"}, {"id": "1539d2a1-2af0-4f8f-871d-96858eb3d24e", "type": "concept", "title": "Uncertainty and population reference samples"}], "description": "Students learn the limits and responsibilities of inferring identity or behavior from skeletal remains."}]}, {"id": "2e5346c2-6f44-4229-9560-3409861b70d9", "type": "topic", "title": "Fossilization, Dating, and Paleoanthropological Evidence", "description": "Human evolution is reconstructed from fragmentary traces preserved in geological context. This unit teaches students how paleoanthropologists build evidence from fossils, sites, sediments, dates, and comparative anatomy.", "children": [{"id": "e2fd6576-fdbc-48a0-9951-8cb42377fb8b", "type": "subtopic", "title": "Fossilization and site formation", "children": [{"id": "ceccecd7-ff4b-4f3b-bc35-894b6dc51368", "type": "concept", "title": "Taphonomy"}, {"id": "3e9e298b-338f-4872-9c86-57c455678bb0", "type": "concept", "title": "Preservation bias"}, {"id": "ee3eccf9-5fda-4222-bce1-ab9bf650fc80", "type": "concept", "title": "Depositional context"}], "description": "Students learn why fossil evidence is rare, biased, and context-dependent."}, {"id": "dd73d8e6-07fc-4f17-bebc-c80901deba2e", "type": "subtopic", "title": "Dating methods and chronology", "children": [{"id": "8caf61e7-6736-44d0-914e-cf6e454a730d", "type": "concept", "title": "Stratigraphy"}, {"id": "8e87b816-9341-4a3b-af20-7e5cc9a4b2d9", "type": "concept", "title": "Radiometric dating"}, {"id": "fdc70a09-ae68-4976-8487-4739e2883ac7", "type": "concept", "title": "Paleomagnetism and biostratigraphy"}], "description": "This subtopic introduces relative and absolute dating methods used to place fossils and artifacts in time."}, {"id": "ed7c185f-0f6f-4d02-b048-4a288876f9a2", "type": "subtopic", "title": "Comparative fossil analysis", "children": [{"id": "82349d95-816a-4a4e-9459-e0876ed6d271", "type": "concept", "title": "Cranial and dental traits"}, {"id": "f3fb9495-0380-4d02-a511-62187520cb6a", "type": "concept", "title": "Postcranial anatomy"}, {"id": "230598b4-7e0f-45e1-97fb-05f09d2f825a", "type": "concept", "title": "Mosaic evolution"}], "description": "Students practice reading fossil traits as evidence for evolutionary relationships and behavior."}]}, {"id": "eea09093-2da7-4334-9e29-93884b424309", "type": "topic", "title": "Early Hominins and the Evolution of Bipedalism", "description": "Bipedalism is one of the defining shifts in hominin evolution. This unit examines early hominins, environmental context, locomotor anatomy, and debates about why upright walking evolved.", "children": [{"id": "57880317-ce76-47c4-8404-66d04ee37479", "type": "subtopic", "title": "Defining hominins", "children": [{"id": "0a629717-bb6a-4d19-a554-3a2e722b7397", "type": "concept", "title": "Hominin versus hominoid"}, {"id": "16ddacad-8ef5-495a-ae96-78a97b074bf4", "type": "concept", "title": "Canine reduction"}, {"id": "5c799618-0921-4b9c-ac20-be8c8ca34694", "type": "concept", "title": "Bipedal indicators"}], "description": "Students learn how scientists identify early members of the human lineage."}, {"id": "a190deed-f016-47a0-9c07-39a0f02af397", "type": "subtopic", "title": "Key early hominin taxa", "children": [{"id": "105671eb-152f-420e-ab97-c75591065a04", "type": "concept", "title": "Sahelanthropus, Orrorin, and Ardipithecus"}, {"id": "6ce409b1-dbb2-4813-bc4e-903f97621437", "type": "concept", "title": "Australopithecus"}, {"id": "fa762105-0377-47bb-8fac-1e8c35b3c07b", "type": "concept", "title": "Paranthropus"}], "description": "This subtopic surveys major fossil groups and what they reveal."}, {"id": "9a469f87-b8f3-436b-9b64-ef04cca939da", "type": "subtopic", "title": "Bipedalism and environment", "children": [{"id": "9d2a9f25-cce6-451e-b88a-f3fe515f5b1f", "type": "concept", "title": "Pelvis, femur, foot, and spine"}, {"id": "a723b800-12ca-4e12-a667-ff352dd17525", "type": "concept", "title": "Savanna and woodland debates"}, {"id": "a7842f17-781a-4c0d-958d-cc1f11b55b77", "type": "concept", "title": "Costs and benefits of bipedality"}], "description": "Students evaluate hypotheses linking locomotion, ecology, energy, provisioning, and climate."}]}, {"id": "dff789f2-1b13-451f-a580-c8dd8e221d3e", "type": "topic", "title": "Genus Homo, Technology, and Pleistocene Dispersals", "description": "This unit follows the emergence of Homo and the expansion of hominins across Africa and Eurasia. Students connect anatomy, brains, tools, diet, cooperation, and changing environments.", "children": [{"id": "e7cb8735-fd70-4405-91e4-911594f16e47", "type": "subtopic", "title": "Early Homo and adaptive shifts", "children": [{"id": "639fa854-2365-4e0f-88f3-bf14e45fd6f6", "type": "concept", "title": "Brain and body size"}, {"id": "46672609-1339-4285-a5f9-16f7e3ca006d", "type": "concept", "title": "Diet and foraging"}, {"id": "c6d41018-8c2d-45c6-8f59-f5d3ce4109dd", "type": "concept", "title": "Oldowan technology"}], "description": "Students examine anatomical and behavioral changes associated with early Homo."}, {"id": "157aa12a-97f2-482c-a8dd-7b20173b71c3", "type": "subtopic", "title": "Homo erectus and dispersal", "children": [{"id": "a65bfe9f-dc59-450e-8090-d0a457482e16", "type": "concept", "title": "Out of Africa I"}, {"id": "3012f606-2602-4d60-8537-971fde341bc8", "type": "concept", "title": "Acheulean handaxes"}, {"id": "36d0f3af-7615-4d56-b469-a73500d7cf64", "type": "concept", "title": "Fire and ranging behavior"}], "description": "This subtopic studies long-distance movement, Acheulean tools, endurance, and ecological flexibility."}, {"id": "25348c85-a9f7-4aa1-b7b8-bd2ba3066933", "type": "subtopic", "title": "Pleistocene variability", "children": [{"id": "cf4fafdd-3354-41c7-9e9b-4439e8729c00", "type": "concept", "title": "Regional populations"}, {"id": "ff53cb74-4046-4fb5-9208-9e761332afef", "type": "concept", "title": "Climate cycles"}, {"id": "17cb0d24-e7ea-4fbe-9e7d-434fc62c20ce", "type": "concept", "title": "Species debates"}], "description": "Students learn that Homo evolution was branching, regional, and diverse rather than linear."}]}, {"id": "afac4d4b-2ab1-476d-a179-0f92cc654827", "type": "topic", "title": "Neanderthals, Denisovans, Ancient DNA, and Admixture", "description": "Ancient DNA has transformed human origins research. This unit examines late archaic humans, interbreeding, adaptation, extinction, and how genetic evidence changes fossil interpretation.", "children": [{"id": "646ccba8-aeb6-4205-8684-84640da67345", "type": "subtopic", "title": "Neanderthal biology and behavior", "children": [{"id": "f6f750fb-c59e-418c-98e7-829030380880", "type": "concept", "title": "Cold adaptation"}, {"id": "bd9a1b91-5b04-404b-aff4-75e4ded4a4e6", "type": "concept", "title": "Mousterian technology"}, {"id": "9437efa3-24f7-421e-af67-5afaad20e569", "type": "concept", "title": "Burial and symbolic behavior"}], "description": "Students examine Neanderthal anatomy, ecology, tools, care, symbolism, and debates about cognition."}, {"id": "28730ce2-c81a-4d6c-a9c2-71dd89812e73", "type": "subtopic", "title": "Denisovans and other archaic populations", "children": [{"id": "3f8bbd64-01cb-48c1-95ea-8189f27ff40a", "type": "concept", "title": "Denisovan DNA"}, {"id": "c8667ed7-fe56-4d60-9f78-d8a3a2bd1629", "type": "concept", "title": "Asian and Oceanian ancestry"}, {"id": "6971e17b-0ec8-4d3f-8e3f-884d1986720a", "type": "concept", "title": "Ghost populations"}], "description": "This subtopic introduces genetic lineages known from limited fossil evidence."}, {"id": "f5f920bd-43ba-4564-b45b-200e9b377eb3", "type": "subtopic", "title": "Ancient DNA and admixture", "children": [{"id": "71126136-ef1f-4b0f-968d-7be70706edaa", "type": "concept", "title": "Introgression"}, {"id": "4beab602-e552-458f-9f68-32a6272e93f9", "type": "concept", "title": "Adaptive variants"}, {"id": "72beb0d0-aab4-44af-8869-1803bc2f0d10", "type": "concept", "title": "Contamination and consent"}], "description": "Students learn how genomes reveal interbreeding and adaptation while raising ethical and interpretive questions."}]}, {"id": "e4eaef38-a8d3-4260-8d7b-f73c824ddbf6", "type": "topic", "title": "Modern Human Origins, Culture, and Symbolic Behavior", "description": "This unit examines the emergence and dispersal of Homo sapiens, emphasizing the interaction of biology, behavior, ecology, and culture. Students learn how modernity is debated through multiple lines of evidence.", "children": [{"id": "a52ae863-29c8-448c-a9f4-7a242bd64f77", "type": "subtopic", "title": "Origins of Homo sapiens", "children": [{"id": "0ceb7a9f-e144-40d2-a803-19c056c6271b", "type": "concept", "title": "African origins"}, {"id": "0e1c01de-76a1-4d4f-b03b-da2b7bccf33a", "type": "concept", "title": "Population structure"}, {"id": "f6497a07-d1a8-47f7-bf03-ec2e891716bc", "type": "concept", "title": "Out of Africa II"}], "description": "Students compare fossil, genetic, and archaeological evidence for modern human origins."}, {"id": "45561f88-4f5c-4394-aa50-0f4ce371dbc8", "type": "subtopic", "title": "Behavioral complexity", "children": [{"id": "b4a3692b-fbed-4c63-a0b3-3249517f7ed8", "type": "concept", "title": "Middle Stone Age innovations"}, {"id": "77e2d0f8-baae-4e89-949b-e8e9d4c1eda2", "type": "concept", "title": "Symbolic artifacts"}, {"id": "19e6a278-fe5a-441e-b754-598d3078e0cd", "type": "concept", "title": "Language and social learning"}], "description": "This subtopic examines tools, art, ornaments, burials, long-distance exchange, and symbolic communication."}, {"id": "2ce6dc6f-ae89-474b-810d-8deb99d73219", "type": "subtopic", "title": "Migration and adaptation", "children": [{"id": "3ba1d682-ea3d-4f5e-85ea-7a312c8493ab", "type": "concept", "title": "Coastal and inland routes"}, {"id": "c0ef85f0-335c-43e8-a5b1-7eaa2aaab0cd", "type": "concept", "title": "Sahul and the Americas"}, {"id": "6d4018c1-c0a3-4b05-8901-214e76571fc8", "type": "concept", "title": "Local adaptation"}], "description": "Students connect dispersal with climate, ecology, technology, and population contact."}]}, {"id": "6b8bcbe1-69ee-4afe-b80c-97155239d779", "type": "topic", "title": "Human Biological Variation and the Critique of Race", "description": "Biological anthropology has a responsibility to explain human variation accurately and challenge racial typologies. This unit teaches students why race is not a valid biological taxonomy while racism has real biological consequences.", "children": [{"id": "6bf79ee0-c7c4-4cf4-8683-a870a7abcd39", "type": "subtopic", "title": "Patterns of human variation", "children": [{"id": "47e4e2d4-896a-4174-86df-76d88bfdc3d3", "type": "concept", "title": "Clines"}, {"id": "1b6ef3ee-371f-495a-b363-45d22e334b37", "type": "concept", "title": "Within-group variation"}, {"id": "1ef2fc51-a2f4-4c7b-8123-62bc358cfb68", "type": "concept", "title": "Gene flow and migration"}], "description": "Students learn that human traits vary clinally, historically, and adaptively rather than as bounded races."}, {"id": "827e8e84-aa14-4882-b43f-ddfbc5ec763a", "type": "subtopic", "title": "Race, racism, and biology", "children": [{"id": "f607ac56-8a23-4ccd-93ec-1cf9c5dfe51f", "type": "concept", "title": "Race as social classification"}, {"id": "d652ae94-54d2-46f1-94fb-8217e574f297", "type": "concept", "title": "Ancestry versus race"}, {"id": "f1dad751-5e86-4e20-8de1-ae700f21968e", "type": "concept", "title": "Embodiment of inequality"}], "description": "This subtopic distinguishes social race from biological ancestry and examines the health effects of racism."}, {"id": "fe87a0e6-7fe4-45ac-acd0-fad047fca24a", "type": "subtopic", "title": "Communicating variation responsibly", "children": [{"id": "40e7b888-6781-4dcd-8b5d-89f4eba34d17", "type": "concept", "title": "Trait complexity"}, {"id": "4c2eb080-600d-4740-bd8d-f11071dbfb0f", "type": "concept", "title": "Population labels"}, {"id": "aeb9ad6d-8eba-4c74-a31d-414f6a56475e", "type": "concept", "title": "Ethical communication"}], "description": "Students practice avoiding genetic determinism, typological thinking, and misuse of ancestry data."}]}, {"id": "4d50ffe3-7eb5-4c5c-92b6-8fc13a371cc0", "type": "topic", "title": "Human Adaptation: Climate, Diet, Disease, and Altitude", "description": "Humans adapt biologically and culturally to diverse environments. This unit examines thermoregulation, nutrition, disease ecology, altitude, skin pigmentation, and gene-culture coevolution.", "children": [{"id": "8cc82432-714e-4d8f-9aa2-d66c71706c3d", "type": "subtopic", "title": "Climate and body form", "children": [{"id": "bedbdd3e-bd9b-4d05-852f-1a9c98e91983", "type": "concept", "title": "Bergmann's and Allen's rules"}, {"id": "da52d376-89ec-4813-9615-8544af782f96", "type": "concept", "title": "Heat and cold stress"}, {"id": "ac8ee9f9-6dea-43b9-881e-d211789ae7c4", "type": "concept", "title": "Plasticity and acclimatization"}], "description": "Students learn how body size, limb proportions, and physiology relate to thermal environments."}, {"id": "6eb8c5e3-3053-4400-9568-92af1c9ec214", "type": "subtopic", "title": "Diet and gene-culture coevolution", "children": [{"id": "b1da52da-acac-4f69-9887-a7636f813117", "type": "concept", "title": "Lactase persistence"}, {"id": "bd4e5ee2-a73b-4423-ae2d-0a744b605e2e", "type": "concept", "title": "Amylase variation"}, {"id": "13651612-c50c-42c3-8e05-5f5eb3315895", "type": "concept", "title": "Agriculture and selection"}], "description": "This subtopic connects subsistence, agriculture, lactose digestion, starch digestion, and microbiomes."}, {"id": "3dbbcc16-bded-42e9-9146-628afd40c186", "type": "subtopic", "title": "Disease and altitude adaptation", "children": [{"id": "7b4ac502-2cd7-4916-8b13-08fd6dda63ee", "type": "concept", "title": "Balanced polymorphism"}, {"id": "b8aef18f-7393-40ed-a2d5-186e2d8c50ba", "type": "concept", "title": "Hypoxia adaptation"}, {"id": "1d7d78bd-32fb-46cb-9776-5ddaaf3bcd1c", "type": "concept", "title": "Pathogens and selection"}], "description": "Students study malaria, sickle-cell traits, immune variation, and high-altitude physiology."}]}, {"id": "3da9b89b-2ea1-45ad-b1b5-f2bda5fe85b8", "type": "topic", "title": "Life History, Growth, Development, and Reproduction", "description": "Human bodies are shaped across the life course. This unit examines growth, childhood, adolescence, reproduction, aging, and the evolutionary tradeoffs that make human life history distinctive.", "children": [{"id": "983baa89-2815-4270-8f40-287af8b0cca4", "type": "subtopic", "title": "Human growth and development", "children": [{"id": "7654db15-de41-465f-9db3-8fe013016781", "type": "concept", "title": "Growth curves"}, {"id": "f6e5763d-43f7-4a1c-9214-1263622974a8", "type": "concept", "title": "Developmental plasticity"}, {"id": "6f83b3f7-fd8d-4d0d-83a0-2fbf3124ae8f", "type": "concept", "title": "Stress and nutrition"}], "description": "Students learn how biology, nutrition, stress, culture, and environment shape development."}, {"id": "7fe2cb07-4145-4e60-ae8c-b4395c18ccab", "type": "subtopic", "title": "Reproductive ecology", "children": [{"id": "5193a67f-8b3b-4cc9-82e1-a076ebe44f48", "type": "concept", "title": "Energetics and fertility"}, {"id": "af89817a-4d53-4c09-bbc0-95332048dc39", "type": "concept", "title": "Parental investment"}, {"id": "c3791fff-f38c-40cc-9f18-2ed9d630df66", "type": "concept", "title": "Alloparenting"}], "description": "This subtopic introduces fertility, parental investment, cooperative breeding, and reproductive tradeoffs."}, {"id": "cd659319-1a01-4b4e-95f5-94e933503b72", "type": "subtopic", "title": "Aging and life history", "children": [{"id": "6282ae31-3de1-4fbd-bccd-c81072536427", "type": "concept", "title": "Life-history tradeoffs"}, {"id": "0be9ce46-6d1b-4635-af93-e049f7ae5f02", "type": "concept", "title": "Grandmother hypothesis"}, {"id": "a1c74d90-76e1-464c-ae55-06594542555a", "type": "concept", "title": "Aging and social support"}], "description": "Students examine longevity, grandparents, menopause, senescence, and intergenerational support."}]}, {"id": "1e988e5e-4ea4-4fb6-8b6f-7fd605a182b7", "type": "topic", "title": "Bioarchaeology: Reconstructing Lives from Human Remains", "description": "Bioarchaeology uses skeletal and contextual evidence to reconstruct health, diet, labor, violence, migration, and inequality in past populations. Students learn how bones become social evidence.", "children": [{"id": "1cd95439-ca61-4313-8d34-c032a0ff861c", "type": "subtopic", "title": "Paleopathology and health", "children": [{"id": "4a55b093-eac9-4dc7-832f-6520deb9ad28", "type": "concept", "title": "Stress markers"}, {"id": "abf5a70e-bad5-4529-959c-3e5e829df6b0", "type": "concept", "title": "Trauma and fracture"}, {"id": "6d9dd418-3531-4ff2-913c-082121268e73", "type": "concept", "title": "Infectious and degenerative disease"}], "description": "Students learn how disease, trauma, stress, and nutrition can leave skeletal traces."}, {"id": "5ee2beca-c93b-420c-bf5e-451622ced4f3", "type": "subtopic", "title": "Diet, mobility, and isotopes", "children": [{"id": "963d3efe-fe0a-4825-9772-a90f1999e938", "type": "concept", "title": "Stable isotopes"}, {"id": "f20468d4-4148-4983-8d60-08f0c86988d1", "type": "concept", "title": "Strontium and oxygen"}, {"id": "36c35ea3-a652-4630-ba0e-dfa05e2b5e57", "type": "concept", "title": "Dental calculus and residues"}], "description": "This subtopic introduces chemical methods for reconstructing past lives."}, {"id": "1305b23a-b99f-4d08-ba2a-3850b38d411a", "type": "subtopic", "title": "Population and social context", "children": [{"id": "4b2185c3-ab33-4aa4-93e3-f4e460d7522e", "type": "concept", "title": "Mortuary context"}, {"id": "3e5cfdf5-3b13-4df5-ac12-438a3a78205d", "type": "concept", "title": "Activity patterns"}, {"id": "892eb3df-d567-4e4a-b9a0-3ae24b4c6f40", "type": "concept", "title": "Population-level interpretation"}], "description": "Students connect skeletal patterns with archaeology, history, environment, and inequality."}]}, {"id": "6a11a868-df09-41d0-8821-3d4ae0df162a", "type": "topic", "title": "Forensic Anthropology and Human Identification", "description": "Forensic anthropology applies skeletal expertise to legal and humanitarian contexts. This unit introduces methods of identification while emphasizing uncertainty, ethics, and the limits of biological profiles.", "children": [{"id": "2fec0e0c-1b22-40b4-b8eb-cf8bd78d3c95", "type": "subtopic", "title": "Forensic context and recovery", "children": [{"id": "51ac3a9c-ea62-4229-b237-bcb73283f1c5", "type": "concept", "title": "Search and recovery"}, {"id": "620259c1-ce84-4b7f-a59b-8346860671f6", "type": "concept", "title": "Chain of custody"}, {"id": "177f9ad7-b375-46ca-96a5-c849e884b106", "type": "concept", "title": "Postmortem interval"}], "description": "Students learn how scene recovery, chain of custody, taphonomy, and documentation shape forensic analysis."}, {"id": "6066dcca-ffe1-4f61-9af3-456dd1087cd9", "type": "subtopic", "title": "Biological profile", "children": [{"id": "984e3e68-db26-497a-bf76-aa8fdcabdf3b", "type": "concept", "title": "Age and sex estimation"}, {"id": "7aeefb48-9cab-48f3-83f7-25f221e9cc08", "type": "concept", "title": "Stature and ancestry estimation"}, {"id": "fc85e7ba-c4e3-48fc-9623-075751e43f09", "type": "concept", "title": "Antemortem and perimortem trauma"}], "description": "This subtopic introduces estimation of age, sex, ancestry, stature, trauma, and individualizing features."}, {"id": "58e13494-e911-4eab-85e4-ba8e7bdff85c", "type": "subtopic", "title": "Human rights and disaster contexts", "children": [{"id": "f773b0a0-58fd-45f2-b4a6-4703641f63fe", "type": "concept", "title": "Humanitarian forensics"}, {"id": "227e9266-6f72-403d-9e0f-9caf44420215", "type": "concept", "title": "Mass graves"}, {"id": "d50ab1f8-0f82-43d2-8909-e3a8ce578650", "type": "concept", "title": "Family and community accountability"}], "description": "Students examine forensic anthropology in mass disasters, missing persons, war crimes, and migrant death investigations."}]}, {"id": "cccf68f0-124d-46fa-8f9b-3e22f7c8ab20", "type": "topic", "title": "Evolutionary Medicine and Human Health", "description": "Evolutionary medicine uses evolutionary theory to explain vulnerability, adaptation, mismatch, and disease. This unit shows how biological anthropology can inform contemporary health without reducing health to genes.", "children": [{"id": "3c49ce06-e95c-45d1-ae9a-1f747fe69920", "type": "subtopic", "title": "Mismatch and modern environments", "children": [{"id": "af070d4c-b06f-4ebf-b616-2b045b09ee46", "type": "concept", "title": "Thrifty genotype and phenotype debates"}, {"id": "87520972-96d0-4d03-8b13-6012d1ea89a8", "type": "concept", "title": "Sedentism and diet"}, {"id": "6f68307f-442e-415a-81d9-ae3d2fbb9502", "type": "concept", "title": "Sleep, stress, and urban life"}], "description": "Students examine how evolved traits interact with rapid changes in diet, activity, pathogens, and built environments."}, {"id": "eeec29c4-51c5-44cc-9c18-aedc8fad4dd4", "type": "subtopic", "title": "Pathogens, immunity, and evolution", "children": [{"id": "cc76ef6d-7a58-4ae9-8df1-e128ccac07e9", "type": "concept", "title": "Host-pathogen coevolution"}, {"id": "fe84c821-dfe4-42b0-a793-f276c64b2461", "type": "concept", "title": "Microbiome diversity"}, {"id": "17bab297-d81e-4fdb-aa9d-193a9a23af55", "type": "concept", "title": "Antibiotic resistance"}], "description": "This subtopic connects infectious disease, immune variation, microbiomes, and coevolution."}, {"id": "e3fd4236-8d7a-4061-a9a7-a453c0593ca9", "type": "subtopic", "title": "Biocultural health", "children": [{"id": "ed6eea8c-1183-4cff-943c-9c924a4928bd", "type": "concept", "title": "Embodiment"}, {"id": "da706949-fe95-4e41-aca0-5d3bfb3805fd", "type": "concept", "title": "Structural violence"}, {"id": "ec7bb43a-ce9a-4538-9e16-01b8def27593", "type": "concept", "title": "Health disparities"}], "description": "Students learn to integrate biology, culture, political economy, inequality, and lived environments."}]}, {"id": "5e47ab25-b803-4be2-b1df-bd05d684b511", "type": "topic", "title": "Ethics, Repatriation, Community Collaboration, and Public Anthropology", "description": "Biological anthropology works with human remains, living communities, genetic data, and sensitive histories. This unit centers consent, repatriation, descendant communities, anti-racism, and public communication.", "children": [{"id": "7f530a89-9a7e-4979-9867-5543db5b5e93", "type": "subtopic", "title": "Ethics of human remains", "children": [{"id": "37c1cd00-ff66-414b-86e7-ff7ca7bbc190", "type": "concept", "title": "Respect and dignity"}, {"id": "3e626e19-8477-49d0-b5c3-d02585609aaf", "type": "concept", "title": "Consent and permissions"}, {"id": "3a76cffc-49ea-495c-9d4e-bb7119cef4d6", "type": "concept", "title": "Curation and access"}], "description": "Students learn why excavation, storage, display, teaching, and research on remains require special responsibility."}, {"id": "519eaf20-7add-4a4b-abf5-f29a839e074c", "type": "subtopic", "title": "Repatriation and descendant communities", "children": [{"id": "c91d720e-30cd-40ed-92d8-fdac9a4d4823", "type": "concept", "title": "NAGPRA and repatriation"}, {"id": "852ba1c1-57f9-4802-b824-e27df12ef792", "type": "concept", "title": "Community consultation"}, {"id": "8fffafd3-324b-4180-9130-57528465697e", "type": "concept", "title": "Collaborative research"}], "description": "This subtopic examines legal and ethical obligations to Indigenous and descendant communities."}, {"id": "5279957f-4292-46b6-9aec-dc585e3e8272", "type": "subtopic", "title": "Public communication and misuse", "children": [{"id": "16ba0749-2efb-4706-8207-1ff7217f10d2", "type": "concept", "title": "Anti-racist science communication"}, {"id": "0fb84daf-f29b-4ae4-83ce-3339330318ae", "type": "concept", "title": "Combatting pseudoscience"}, {"id": "217c9ac6-40e6-4ddf-b7d3-7e90072c989f", "type": "concept", "title": "Public trust and transparency"}], "description": "Students practice communicating evolution, variation, ancestry, and fossils responsibly."}]}, {"id": "4ee1ca8c-cc0c-4728-a510-ee9d953e912d", "type": "topic", "title": "Capstone: Human Evolution Evidence Portfolio", "description": "The course culminates in a project where students synthesize fossils, genetics, primatology, skeletal evidence, ethics, and public communication. The goal is to reason like a biological anthropologist with multiple forms of evidence.", "children": [{"id": "2c6cd1b6-be84-4eb7-bd5e-4ba6ddef098e", "type": "subtopic", "title": "Research question and evidence map", "children": [{"id": "b224f6de-8ab1-4b94-a342-fa89caf8afd2", "type": "concept", "title": "Question design"}, {"id": "9bd16c93-0faa-43b6-ada9-cb1b301ee40c", "type": "concept", "title": "Evidence types"}, {"id": "639d23dc-4375-489e-a0d0-aee0e8d97015", "type": "concept", "title": "Competing hypotheses"}], "description": "Students define a focused question and identify the evidence needed to answer it."}, {"id": "b0b08848-e46e-4a13-86ce-d365972db200", "type": "subtopic", "title": "Analysis and interpretation", "children": [{"id": "e686e483-9d1b-425d-a0e7-4d6514bde222", "type": "concept", "title": "Trait comparison"}, {"id": "7c0c66f7-b548-4d31-be6e-65fdf57c9d01", "type": "concept", "title": "Data quality"}, {"id": "81a080ad-1a83-45f0-8708-91cfa10f0ba9", "type": "concept", "title": "Uncertainty and limits"}], "description": "This subtopic guides students through evaluating fossil, genetic, comparative, or skeletal evidence."}, {"id": "17a52982-c116-4005-a552-ebe0dc2229e8", "type": "subtopic", "title": "Public-facing synthesis", "children": [{"id": "16f28412-62ef-4d6f-b4c5-4a8f5aa24c4c", "type": "concept", "title": "Clear explanation"}, {"id": "a0f899ba-843b-45b7-a39c-8a590acd1bf4", "type": "concept", "title": "Ethical caveats"}, {"id": "7c171f04-f7d4-4fa9-b00b-946f30e7b419", "type": "concept", "title": "Visual or public communication"}], "description": "Students translate their findings into a short paper, exhibit text, poster, or digital brief."}]}], "dbBacked": true}$bpanjson$::jsonb,
